// Siempre devuelve un link para ver: el que cargó el coach, o si no, un video real de la técnica
// según el tipo de movimiento, o como último recurso una búsqueda de YouTube.
function videoDe(pe) {
  if (pe.video) return pe.video;
  const cat = VIDEOS_POR_CATEGORIA.find((c) => c.match.test(pe.nombre));
  if (cat) return cat.video;
  return `https://www.youtube.com/results?search_query=${encodeURIComponent(pe.nombre + " técnica")}`;
}

/* =========================================================
   MODELO DE PLAN
   ========================================================= */
const mkRow = (nombre, overrides = {}) => {
  const { s1, s2, s3, s4, s5, s6, s7, s8, semanas, nota = "", rm = "", rmSemanas, rir = "", descanso = "90", tipo = "normal", tabata = null, video = null, rol = null, sinDescansoSiguiente = false, circuito = false, ...rest } = overrides;
  const legacy = [s1, s2, s3, s4, s5, s6, s7, s8].filter((v) => v !== undefined);
  const semanasFinal = semanas || (legacy.length ? legacy : [""]);
  return {
    id: uid(), nombre, video, nota, rm, rir, descanso, tipo, rol, sinDescansoSiguiente, circuito,
    tabata: tabata || { trabajo: 20, descanso: 10, rounds: 8 },
    semanas: semanasFinal,
    // RM/RIR por semana (ej: 70% semana 1, 80% semana 3). Si una semana no tiene su propio valor
    // cargado, se usa "rm" (el campo viejo, de un solo valor) como respaldo — así los planes
    // guardados antes de este cambio se siguen viendo igual.
    rmSemanas: rmSemanas || semanasFinal.map(() => ""),
    ...rest,
  };
};
// Devuelve el RM/RIR que corresponde a una semana puntual de un ejercicio, con el campo viejo
// de un solo valor como respaldo para planes guardados antes de tener RM por semana.
function rmDeSemana(fila, i) {
  const porSemana = fila.rmSemanas && fila.rmSemanas[i];
  return (porSemana && porSemana.trim()) ? porSemana : (fila.rm || "");
}
const mkRowFromLibrary = (nombreLibreria, overrides = {}) => { const ex = findEx(nombreLibreria); return mkRow(ex ? ex.nombre : nombreLibreria, { video: ex ? ex.video : null, emoji: ex ? ex.emoji : null, ...overrides }); };
const mkBloque = (nombre, ejercicios = []) => ({ id: uid(), nombre, ejercicios });
const mkDia = (nombre, bloques = [], diaSemana = "") => ({ id: uid(), nombre, bloques, diaSemana });
const mkWarm = (nombre, series = "", reps = "", video = null, nota = "") => ({ id: uid(), nombre, series, reps, video, nota });
const DIAS_SEMANA = ["Lunes", "Martes", "Miércoles", "Jueves", "Viernes", "Sábado", "Domingo"];
// Frases rápidas para que el/la alumno/a arme su nota con un toque, sin tener que escribir
// siempre lo mismo. Igual puede escribir libremente en el mismo cuadro, o combinar ambas cosas.
const NOTAS_RAPIDAS = ["Me sentí bien 💪", "Me costó 😓", "Me salió fácil 😌", "Con energía ⚡", "Cansado/a 🥱", "Dolor o molestia ⚠️"];
const todayISO = () => new Date().toISOString().slice(0, 10);
// Racha de constancia: cuántos días de entrenamiento PROGRAMADOS seguidos vino cumpliendo, sin
// cortarse. Solo cuenta los días que realmente le tocaba entrenar (según el día de la semana
// asignado a cada día del plan) — no todos los días del calendario, que no tendría sentido.
function calcularRacha(alumno) {
  const diasProgramados = new Set((alumno.plan?.dias || []).map((d) => d.diaSemana).filter(Boolean));
  if (diasProgramados.size === 0) return 0;
  const sesiones = new Set(alumno.historialSesiones || []);
  let racha = 0;
  const fecha = new Date();
  for (let i = 0; i < 365; i++) {
    const fechaISO = fecha.toISOString().slice(0, 10);
    const nombreDia = DIAS_SEMANA[(fecha.getDay() + 6) % 7];
    if (diasProgramados.has(nombreDia)) {
      if (sesiones.has(fechaISO)) racha++;
      else if (i > 0) break; // si es hoy y todavía no entrenó, no le cortamos la racha — puede entrenar más tarde
    }
    fecha.setDate(fecha.getDate() - 1);
  }
  return racha;
}
// Saca acentos y pasa a minúscula, para que buscar "sentadilla" encuentre "Sentadillа" aunque
// falte una tilde o esté mal escrito el acento — no corrige errores de ortografía en general,
// pero cubre el caso más común (tildes y mayúsculas).
const normalizarTexto = (s) => (s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
// Cuántas letras hay que cambiar/agregar/sacar para pasar de una palabra a la otra — así "sentadila"
// (con error de tipeo) igual encuentra "sentadilla".
function distanciaEdicion(a, b) {
  const m = a.length, n = b.length;
  if (Math.abs(m - n) > 3) return 99; // palabras de largo muy distinto, ni vale la pena comparar
  const fila = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) {
    let anterior = fila[0];
    fila[0] = i;
    for (let j = 1; j <= n; j++) {
      const temp = fila[j];
      fila[j] = a[i - 1] === b[j - 1] ? anterior : 1 + Math.min(anterior, fila[j], fila[j - 1]);
      anterior = temp;
    }
  }
  return fila[n];
}
// Busca por palabras sueltas, no como un bloque de texto exacto — así "flex de brazo" encuentra
// "Flexión de brazo" (le falta el final a una palabra), y tolera algún error de tipeo en cada
// palabra (una letra de más/menos/cambiada cada ~4 letras, aprox.).
// Cumplimiento REAL del/de la alumno/a: sesiones que efectivamente entrenó en las últimas 4
// semanas, contra las que le tocaban según los días de entrenamiento que tiene su plan actual.
// Antes era un número fijo que quedaba pisado en 0 desde que se creaba el alumno y nunca se
// volvía a tocar — por eso no se "actualizaba". Ahora se calcula solo, siempre con datos frescos.
function calcularCumplimiento(alumno) {
  const diasPorSemana = (alumno.plan?.dias || []).length;
  if (!diasPorSemana) return 0;
  const hoyMs = Date.now();
  const hace28Ms = hoyMs - 28 * 24 * 60 * 60 * 1000;
  const sesionesRecientes = (alumno.historialSesiones || []).filter((f) => {
    const t = new Date(f + "T00:00:00").getTime();
    return t >= hace28Ms && t <= hoyMs;
  }).length;
  const esperadas = diasPorSemana * 4;
  return Math.min(100, Math.round((sesionesRecientes / esperadas) * 100));
}

function coincideBusqueda(nombre, busqueda) {
  const palabrasBusqueda = normalizarTexto(busqueda).split(/\s+/).filter(Boolean);
  if (palabrasBusqueda.length === 0) return true;
  const palabrasNombre = normalizarTexto(nombre).split(/\s+/).filter(Boolean);
  return palabrasBusqueda.every((pb) =>
    palabrasNombre.some((pn) => pn.startsWith(pb) || pn.includes(pb) || distanciaEdicion(pb, pn) <= Math.max(1, Math.floor(pb.length / 4)))
  );
}
// ---------- Nombres de ejercicios que son "el mismo" ----------
// Para que "hip trust", "Hip Thrust" e "hipthrust" sean el mismo RM, y "press de pecho" o
// "banco plano" se relacionen con "Press banca plano". Primero se limpia el nombre (tildes,
// mayúsculas, letras repetidas, "th"), después se pasa por una lista de sinónimos comunes del
// gimnasio y, si todavía no coincide, se tolera algún error de tipeo.
const SINONIMOS_EJERCICIO = [
  ["press banca plano", ["press de pecho", "press pecho", "banco plano", "press banca", "press de banca", "press banco plano", "press plano", "press en banco plano", "bench press", "bench", "pecho plano", "press de pecho plano"]],
  ["press banca inclinado", ["banco inclinado", "press inclinado", "press de pecho inclinado", "incline bench"]],
  ["press banca declinado", ["banco declinado", "press declinado"]],
  ["hip thrust", ["hip trust", "hipthrust", "hip thrus", "empuje de cadera", "puente de gluteo con barra", "elevacion de cadera con barra"]],
  ["sentadilla trasera", ["sentadilla", "sentadillas", "squat", "back squat", "sentadilla libre", "sentadilla con barra", "sentadilla atras"]],
  ["sentadilla frontal", ["front squat", "sentadilla adelante", "sentadilla delantera"]],
  ["peso muerto convencional", ["peso muerto", "deadlift", "pm", "peso muerto clasico"]],
  ["peso muerto rumano", ["rumano", "rdl", "peso muerto piernas rigidas"]],
  ["press militar de pie", ["press militar", "press de hombro", "press hombro", "ohp", "overhead press", "press por encima de la cabeza"]],
  ["dominada", ["dominadas", "pull up", "pullup", "pull ups", "chin up", "chin ups"]],
  ["remo con barra", ["remo barra", "remo inclinado con barra", "barbell row"]],
  ["cargada", ["clean", "power clean", "cargada de potencia"]],
  ["arranque", ["snatch", "power snatch"]],
  ["prensa", ["prensa de piernas", "prensa 45", "leg press"]],
];
function limpiarNombreEjercicio(s) {
  return normalizarTexto(s)
    .replace(/[^a-z0-9ñ ]+/g, " ")
    .replace(/th/g, "t")
    .replace(/([a-z])\1+/g, "$1")
    .replace(/\b(de|del|con|en|la|el|los|las|a|al)\b/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}
const _MAPA_SINONIMOS = (() => {
  const m = new Map();
  SINONIMOS_EJERCICIO.forEach(([canon, alias]) => [canon, ...alias].forEach((x) => m.set(limpiarNombreEjercicio(x), limpiarNombreEjercicio(canon))));
  return m;
})();
// Palabras de variante que no cambian el ejercicio para el RM ("Hip thrust con pausa" usa el RM de
// "Hip thrust"). Unilateral o a una mano no están: ahí el RM es otro.
const PALABRAS_VARIANTE = /\b(pausas?|tempo|lent[oa]|isometric[oa]s?|excentric[oa]s?|enfatizad[oa]|banda|elastica|cadenas?|deficit|cinturon|calzado|rango|medio|velocidad|maxima|tecnica|vacia|repeticiones|3 1 1|1 5)\b/g;
// Clave para comparar dos nombres de ejercicio. Sin la variante (lo que va después de " — " o las
// palabras de variante sueltas).
function claveEjercicio(nombre) {
  const limpio = limpiarNombreEjercicio(String(nombre || "").split(/\s[—–-]\s/)[0]);
  const base = limpio.replace(PALABRAS_VARIANTE, " ").replace(/\s+/g, " ").trim() || limpio;
  return _MAPA_SINONIMOS.get(base) || base;
}
function mismoEjercicio(a, b) {
  const ka = claveEjercicio(a), kb = claveEjercicio(b);
  if (!ka || !kb) return false;
  if (ka === kb) return true;
  const tol = Math.min(ka.length, kb.length) >= 8 ? 2 : 1;
  return distanciaEdicion(ka, kb) <= tol;
}
// De una lista de nombres ya cargados, devuelve el que es "el mismo" ejercicio que el escrito
// (o null). Si hay uno idéntico, gana ese.
function ejercicioRelacionado(nombre, lista) {
  const n = normalizarTexto(nombre).trim();
  if (!n) return null;
  const exacto = lista.find((x) => normalizarTexto(x).trim() === n);
  if (exacto) return exacto;
  // entre los que coinciden, el que está escrito más parecido
  const l = limpiarNombreEjercicio(nombre);
  const candidatos = lista.filter((x) => mismoEjercicio(x, nombre));
  candidatos.sort((a, b) => distanciaEdicion(limpiarNombreEjercicio(a), l) - distanciaEdicion(limpiarNombreEjercicio(b), l));
  return candidatos[0] || null;
}
// Grupo al que pertenece un ejercicio, para mostrar los RM ordenados en grupos que se abren y
// se cierran, en vez de una lista larga suelta.
const GRUPOS_RM = [
  { id: "piernas", label: "Piernas", emoji: "🦵", claves: ["sentadilla", "squat", "prensa", "zancada", "estocada", "bulgara", "extension cuadriceps", "sillon", "pistol", "step up", "subida cajon", "hack"] },
  { id: "cadera", label: "Cadera y glúteo", emoji: "🍑", claves: ["hip trust", "puente", "peso muerto", "rumano", "rdl", "deadlift", "swing", "gluteo", "curl femoral", "isquio", "patada", "abductor", "aductor", "buenos dias"] },
  { id: "empuje", label: "Empuje (pecho y hombro)", emoji: "💪", claves: ["press", "banca", "banco", "pecho", "fondos", "flexion", "push", "militar", "hombro", "aperturas", "jerk", "elevaciones laterales"] },
  { id: "traccion", label: "Tracción (espalda)", emoji: "🧗", claves: ["remo", "dominada", "jalon", "pul", "chin", "espalda", "face", "pulover", "encogimientos"] },
  { id: "olimpico", label: "Olímpicos y potencia", emoji: "🏋️", claves: ["arranque", "cargada", "envion", "clean", "snatch", "salto", "lanzamiento", "balon"] },
  { id: "brazos", label: "Brazos", emoji: "🦾", claves: ["curl", "biceps", "triceps", "frances", "martillo", "antebrazo", "muñeca"] },
  { id: "core", label: "Core", emoji: "🔥", claves: ["plancha", "abdominal", "core", "rueda", "pallof", "giro", "hollow", "lumbar"] },
];
function grupoRM(nombre) {
  const k = claveEjercicio(nombre) + " " + limpiarNombreEjercicio(nombre);
  for (const g of GRUPOS_RM) if (g.claves.some((c) => k.includes(limpiarNombreEjercicio(c)))) return g;
  return { id: "otros", label: "Otros", emoji: "📌", claves: [] };
}
// Ordena una lista de elementos en los grupos de arriba (en ese orden), cada uno ordenado por nombre.
function agruparPorGrupoRM(items, nombreDe) {
  const orden = [...GRUPOS_RM.map((g) => g.id), "otros"];
  const grupos = new Map();
  items.forEach((it) => {
    const g = grupoRM(nombreDe(it));
    if (!grupos.has(g.id)) grupos.set(g.id, { ...g, items: [] });
    grupos.get(g.id).items.push(it);
  });
  return [...grupos.values()]
    .sort((a, b) => orden.indexOf(a.id) - orden.indexOf(b.id))
    .map((g) => ({ ...g, items: g.items.sort((x, y) => String(nombreDe(x)).localeCompare(String(nombreDe(y)), "es")) }));
}
// Calcula qué semana del mesociclo le toca a un alumno HOY, en base a la fecha real de inicio
// que cargó el coach — para que la app arranque ahí sola, y para poder marcarla como "la que toca"
// aunque el alumno esté mirando otra. Si no hay fecha cargada, no recomienda nada (null).
function semanaQueToca(fechaInicio, maxSemanas) {
  if (!fechaInicio) return null;
  const inicio = new Date(fechaInicio + "T00:00:00");
  if (isNaN(inicio.getTime())) return null;
  const diffDias = Math.floor((new Date(todayISO() + "T00:00:00") - inicio) / (1000 * 60 * 60 * 24));
  if (diffDias < 0) return 0; // todavía no arrancó, mostramos semana 1
  const semana = Math.floor(diffDias / 7);
  return Math.max(0, Math.min(semana, maxSemanas - 1));
}
// Convierte una fecha ISO en "hace 5 min", "hace 2 h", "hace 3 días", etc.
// "hoy 19:33", "ayer 08:10" o "lun 12/10 19:33" — para mostrar cuándo fue la última conexión de un/a alumno/a.
function formatoConexion(iso) {
  const d = new Date(iso);
  if (isNaN(d.getTime())) return "";
  const hh = d.toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit", hourCycle: "h23" });
  const hoy = new Date();
  const ayer = new Date(hoy.getTime() - 86400000);
  if (d.toDateString() === hoy.toDateString()) return `hoy ${hh}`;
  if (d.toDateString() === ayer.toDateString()) return `ayer ${hh}`;
  return `${d.toLocaleDateString("es-AR", { weekday: "short", day: "2-digit", month: "2-digit" })} ${hh}`;
}
function tiempoRelativo(iso) {
  const diffMs = Date.now() - new Date(iso).getTime();
  const min = Math.floor(diffMs / 60000);
  if (min < 1) return "recién";
  if (min < 60) return `hace ${min} min`;
  const horas = Math.floor(min / 60);
  if (horas < 24) return `hace ${horas} h`;
  const dias = Math.floor(horas / 24);
  return `hace ${dias} día${dias === 1 ? "" : "s"}`;
}
// Filtra check-ins (u otros registros con fecha "YYYY-MM-DD") para quedarnos solo con los del
// mes en curso — el gráfico "arranca de cero" visualmente cada mes, pero no se borra nada:
// el historial completo sigue guardado, solo dejamos de mostrarlo en el gráfico principal.
const delMesActual = (items) => {
  const prefijoMes = todayISO().slice(0, 7); // "YYYY-MM"
  return items.filter((c) => (c.fecha || "").startsWith(prefijoMes));
};
const fechaLegible = (iso) => { try { return new Date(iso + "T00:00:00").toLocaleDateString("es-AR", { day: "numeric", month: "short" }); } catch { return iso; } };
const mostrarFecha = (f) => (/^\d{4}-\d{2}-\d{2}$/.test(f) ? fechaLegible(f) : f);

function generarTextoPlan(alumno) {
  const p = alumno.plan;
  let t = `🐂 TEAM BULL — Plan de ${alumno.nombre}\n`;
  t += `Objetivo: ${p.meta.objetivo || "—"} | Actividad: ${p.meta.actividad || "—"} | Mesociclo: ${p.meta.mesociclo || "—"} | Fecha: ${p.meta.fecha || "—"}\n\n`;
  if (p.calentamiento.length) {
    t += `ENTRADA EN CALOR\n`;
    p.calentamiento.forEach((w) => { t += `• ${w.nombre}${w.series ? ` — ${w.series}x${w.reps || "?"}` : ""}\n`; });
    t += `\n`;
  }
  if (p.dias.length === 0) {
    t += `Todavía no hay días de entrenamiento cargados en este plan. Andá a la pestaña Plan y agregá al menos un día con ejercicios.\n`;
    return t;
  }
  p.dias.forEach((d) => {
    t += `${d.nombre}${d.diaSemana ? ` (${d.diaSemana})` : ""}\n`;
    if (d.bloques.length === 0 || d.bloques.every((b) => b.ejercicios.length === 0)) {
      t += `  (sin ejercicios cargados en este día)\n`;
    }
    d.bloques.forEach((b) => {
      t += `  ${b.nombre}\n`;
      b.ejercicios.forEach((f) => {
        if (f.tipo === "tabata") {
          t += `  • ${f.nombre} — Tabata ${f.tabata.trabajo}s/${f.tabata.descanso}s x${f.tabata.rounds}\n`;
        } else {
          const sems = f.semanas.map((s, i) => { const r = rmDeSemana(f, i); return `${s || ""}${r ? ` (${r})` : ""}`; }).filter((s) => s.trim()).join(" / ");
          t += `  • ${f.nombre}${f.nota ? ` (${f.nota})` : ""}${sems ? ` — ${sems}` : ""}\n`;
        }
      });
    });
    t += `\n`;
  });
  return t;
}

// Estilos compartidos entre el PDF de un solo plan y el del plantel completo, para que se vean
// igual — oscuros y con los mismos colores de acento que la app (naranja/verde agua), como pidió
// Tomás ("que sea idéntico a la app"). Los nombres de ejercicio con video real cargado son un link
// clickeable directo a YouTube (los que no tienen video real quedan como texto simple, sin link).
const ESTILO_PDF = `
  body{font-family:-apple-system,Helvetica,Arial,sans-serif;background:#121017;color:#F4F1EA;padding:24px;margin:0}
  h1{margin:0 0 2px;font-size:22px;color:#F4F1EA}
  h2{color:#FF6B35;margin:22px 0 2px;font-size:18px}
  h3{margin:16px 0 6px;font-size:14px;color:#F4F1EA;border-bottom:1px solid #322E3D;padding-bottom:4px}
  h4{color:#FF6B35;margin:10px 0 6px;font-size:12px;letter-spacing:.03em;text-transform:uppercase}
  table{border-collapse:collapse;width:100%;margin-bottom:14px;font-size:11.5px;background:#1C1A24;border-radius:8px;overflow:hidden}
  td,th{border:1px solid #322E3D;padding:6px 8px;text-align:left;color:#F4F1EA}
  th{background:#26232F;color:#8B8698;font-weight:600;font-size:10px;text-transform:uppercase}
  td small{color:#7DD6C0;display:block;margin-top:2px}
  .meta{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0 4px}
  .meta span{background:#1C1A24;border:1px solid #322E3D;border-radius:999px;padding:5px 12px;font-size:11px;color:#8B8698}
  .meta b{color:#F4F1EA}
  a.video{color:#7DD6C0;text-decoration:none;font-weight:600}
  a.video:hover{text-decoration:underline}
  .nota{color:#8B8698;font-size:10.5px;font-style:italic}
  .btn-imprimir{display:inline-block;background:#FF6B35;color:#121017;border:none;border-radius:999px;padding:10px 18px;font-size:14px;font-weight:700;cursor:pointer;margin-bottom:18px}
  @media print{.btn-imprimir{display:none} body{background:#121017}}
`;
// Envuelve el nombre del ejercicio en un link a YouTube SOLO si hay un video real cargado
// (no el de fábrica ni el de búsqueda) — así en el PDF nunca aparece un link que no exista de verdad.
const nombreConVideoHTML = (nombre, video) =>
  video ? `<a class="video" href="${video}" target="_blank" rel="noopener noreferrer">▶ ${nombre}</a>` : nombre;

function generarHTMLPlan(alumno) {
  const p = alumno.plan;
  const filaHTML = (f) => `<tr><td>${nombreConVideoHTML(f.nombre, f.video)}${f.nota ? `<div class="nota">${f.nota}</div>` : ""}</td>${f.tipo === "tabata" ? `<td colspan="99">Tabata: ${f.tabata.trabajo}s trabajo / ${f.tabata.descanso}s descanso × ${f.tabata.rounds} rounds</td>` : f.semanas.map((s, i) => { const r = rmDeSemana(f, i); return `<td>${s || "—"}${r ? `<small>${r}</small>` : ""}</td>`; }).join("")}</tr>`;
  const diaHTML = (d) => `<h3>${d.nombre}${d.diaSemana ? ` — ${d.diaSemana}` : ""}</h3>` + d.bloques.map((b) => `<h4>${b.nombre}</h4><table><tr><th>Ejercicio</th>${b.ejercicios[0] && b.ejercicios[0].tipo !== "tabata" ? b.ejercicios[0].semanas.map((_, i) => `<th>Sem.${i + 1}</th>`).join("") : "<th>Detalle</th>"}</tr>${b.ejercicios.map(filaHTML).join("")}</table>`).join("");
  return `<html><head><meta charset="utf-8"><title>Plan — ${alumno.nombre}</title><style>${ESTILO_PDF}</style></head><body>
    <button class="btn-imprimir" onclick="window.print()">🖨️ Imprimir / Guardar como PDF</button>
    <h1>🐂 Team Bull</h1>
    <h2>${alumno.nombre}</h2>
    <div class="meta"><span><b>Objetivo:</b> ${p.meta.objetivo || "—"}</span><span><b>Actividad:</b> ${p.meta.actividad || "—"}</span><span><b>Mesociclo:</b> ${p.meta.mesociclo || "—"}</span><span><b>Fecha:</b> ${p.meta.fecha || "—"}</span></div>
    ${p.calentamiento.length ? `<h4>Entrada en calor</h4><table><tr><th>Ejercicio</th><th>Series</th><th>Reps</th></tr>${p.calentamiento.map((w) => `<tr><td>${nombreConVideoHTML(w.nombre, w.video)}${w.nota ? `<div class="nota">${w.nota}</div>` : ""}</td><td>${w.series || "—"}</td><td>${w.reps || "—"}</td></tr>`).join("")}</table>` : ""}
    ${p.dias.map(diaHTML).join("")}
  </body></html>`;
}

// Enviar por WhatsApp directo (más confiable que el share nativo: no depende de permisos del navegador)
function compartirPorWhatsApp(alumno) {
  const texto = generarTextoPlan(alumno);
  const url = `https://wa.me/?text=${encodeURIComponent(texto)}`;
  window.open(url, "_blank", "noopener,noreferrer");
}

// Descarga el plan como archivo .html al dispositivo
function descargarPlanPDF(alumno) {
  const html = generarHTMLPlan(alumno);
  const blob = new Blob([html], { type: "text/html" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `Plan-${slugify(alumno.nombre)}.html`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

// Genera un solo documento con TODOS los alumnos, uno abajo del otro (con salto de página entre
// cada uno), para descargar de una sola vez en vez de tener que hacerlo alumno por alumno.
function generarHTMLPlantel(alumnos) {
  const secciones = alumnos.map((a) => {
    const html = generarHTMLPlan(a);
    // Sacamos el <html><head>...</head><body> de cada uno, nos quedamos solo con el contenido de adentro
    const match = html.match(/<body[^>]*>([\s\S]*)<\/body>/);
    return `<div style="page-break-before: always; padding-top: 20px;">${match ? match[1] : html}</div>`;
  }).join("");
  return `<html><head><meta charset="utf-8"><title>Team Bull — Plantel completo</title><style>${ESTILO_PDF}</style></head><body>
    <button class="btn-imprimir" onclick="window.print()">🖨️ Imprimir / Guardar como PDF</button>
    <h1>🐂 Team Bull — Plantel completo (${alumnos.length} alumnos/as)</h1>
    ${secciones}
  </body></html>`;
}
function descargarPlantelPDF(alumnos) {
  const html = generarHTMLPlantel(alumnos);
  const blob = new Blob([html], { type: "text/html" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `TeamBull-Plantel-completo-${todayISO()}.html`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

// Abre el panel nativo de compartir (WhatsApp, copiar, mail, etc.) con el plan como texto,
// o si el dispositivo soporta compartir archivos, adjunta el HTML directamente.
async function compartirPlan(alumno) {
  const texto = generarTextoPlan(alumno);
  try {
    const html = generarHTMLPlan(alumno);
    const file = new File([html], `Plan-${slugify(alumno.nombre)}.html`, { type: "text/html" });
    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      await navigator.share({ files: [file], title: `Plan de ${alumno.nombre}`, text: texto });
      return;
    }
    if (navigator.share) {
      await navigator.share({ title: `Plan de ${alumno.nombre}`, text: texto });
      return;
    }
  } catch (e) {
    if (e && e.name === "AbortError") return; // el usuario canceló el share sheet
  }
  // Sin soporte de compartir nativo (ej: desktop): copiamos el texto al portapapeles
  try {
    await navigator.clipboard.writeText(texto);
    alert("Tu navegador no tiene menú para compartir. Copié el plan como texto al portapapeles — pegalo donde quieras (WhatsApp, mail, etc.).");
  } catch {
    descargarPlanPDF(alumno);
  }
}

// Compartir texto genérico por WhatsApp directo (usado por el informe semanal)
// Arma un texto con las notas de ejercicios del alumno, agrupadas por día — para compartir
// por WhatsApp o donde el coach quiera guardarlas (mail, notas, etc.)
function generarTextoNotas(alumno) {
  const porDia = Object.values(alumno.notasEjercicios || {}).filter((n) => n.texto && n.texto.trim()).reduce((acc, n) => { (acc[n.fecha] = acc[n.fecha] || []).push(n); return acc; }, {});
  let t = `📝 Notas de entrenamiento — ${alumno.nombre}\n\n`;
  Object.entries(porDia).sort((a, b) => (a[0] < b[0] ? 1 : -1)).forEach(([fecha, notas]) => {
    t += `📅 ${mostrarFecha(fecha)}\n`;
    notas.forEach((n) => { t += `• ${n.exNombre}: ${n.texto}\n`; });
    t += `\n`;
  });
  return t.trim();
}
function compartirTextoPorWhatsApp(texto) {
  const url = `https://wa.me/?text=${encodeURIComponent(texto)}`;
  window.open(url, "_blank", "noopener,noreferrer");
}

// Compartir texto genérico (usado por el informe semanal)
async function compartirTexto(titulo, texto) {
  try {
    if (navigator.share) { await navigator.share({ title: titulo, text: texto }); return; }
  } catch (e) {
    if (e && e.name === "AbortError") return;
  }
  try {
    await navigator.clipboard.writeText(texto);
    alert("Copiado al portapapeles — pegalo donde quieras.");
  } catch {
    const blob = new Blob([texto], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = `${slugify(titulo)}.txt`;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 2000);
  }
}

// Informe semanal consolidado: encuestas, check-ins y notas de ejercicios de los últimos 7 días, para todos los alumnos
// Informe individual en PDF — versión prolija y profesional, pensada para mandar a la alumna,
// a un club, o guardar como registro (no como texto plano de WhatsApp, que se ve desordenado).
// Gráfico de línea en SVG puro (no depende de React) — para poder incluirlo en el PDF impreso,
// no solo en la pantalla. Mismo estilo visual que los gráficos de la app.
// Gráfico circular (dona) en SVG puro — para porcentajes tipo cumplimiento o ánimo promedio.
function svgDonutChart(valorActual, valorMax, color, textoCentro, label, tamano = 100) {
  const pct = Math.max(0, Math.min(1, valorActual / valorMax));
  const r = tamano * 0.385, cx = tamano / 2 + 2, cy = tamano / 2 + 2, grosor = tamano * 0.096;
  const circun = 2 * Math.PI * r;
  const lleno = circun * pct;
  const vb = tamano + 4;
  return `
    <div style="display:flex;flex-direction:column;align-items:center;background:#F8F6F1;border-radius:12px;padding:${tamano < 90 ? "10px 8px" : "14px 18px"};">
      <div style="font-size:${tamano < 90 ? 8.5 : 10}px;color:#8B8698;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px;text-align:center;">${label}</div>
      <div style="font-size:${tamano < 90 ? 15 : 24}px;font-weight:800;color:#121017;margin-bottom:6px;">${textoCentro}</div>
      <svg width="${tamano}" height="${tamano}" viewBox="0 0 ${vb} ${vb}">
        <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#E8E3D8" stroke-width="${grosor}"/>
        <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${color}" stroke-width="${grosor}" stroke-linecap="round" stroke-dasharray="${lleno} ${circun}" transform="rotate(-90 ${cx} ${cy})"/>
      </svg>
    </div>`;
}
// Gráfico de barras en SVG puro — para comparar valores entre semanas, meses, etc.
function svgBarChart(labels, valores, color, unidad = "") {
  if (!valores.length) return `<div style="color:#8B8698;font-size:12px;">Sin datos.</div>`;
  const w = 640, h = 140, pad = 24, padSup = 20;
  const max = Math.max(...valores, 1);
  const anchoBarra = (w - pad * 2) / valores.length;
  const barras = valores.map((v, i) => {
    const alto = ((h - padSup - pad) * v) / max;
    const x = pad + i * anchoBarra + anchoBarra * 0.18;
    const y = h - pad - alto;
    const anchoReal = anchoBarra * 0.64;
    return `<rect x="${x}" y="${y}" width="${anchoReal}" height="${alto}" rx="4" fill="${color}"/>
      <text x="${x + anchoReal / 2}" y="${y - 6}" text-anchor="middle" font-size="11" font-weight="700" fill="#121017" font-family="-apple-system,sans-serif">${v}${unidad}</text>
      <text x="${x + anchoReal / 2}" y="${h - 6}" text-anchor="middle" font-size="9" fill="#8B8698" font-family="-apple-system,sans-serif">${labels[i]}</text>`;
  }).join("");
  return `<svg viewBox="0 0 ${w} ${h}" style="width:100%;height:auto;display:block;"><line x1="${pad}" y1="${h - pad}" x2="${w - pad}" y2="${h - pad}" stroke="#E8E3D8" stroke-width="1"/>${barras}</svg>`;
}
function svgLineChart(data, color = "#FF6B35", unidad = "") {
  if (!Array.isArray(data) || data.length === 0) return `<div style="color:#8B8698;font-size:12px;padding:14px 0;">Sin datos todavía.</div>`;
  if (data.length === 1) return `<div style="font-size:22px;font-weight:800;padding:10px 0;">${data[0]}${unidad}</div>`;
  const max = Math.max(...data), min = Math.min(...data);
  const actual = data[data.length - 1], inicial = data[0];
  const delta = actual - inicial;
  const fmt = (n) => (Number.isInteger(n) ? n : n.toFixed(1));
  const w = 640, h = 100, pad = 10;
  const pt = (v, i) => [pad + (i * (w - pad * 2)) / (data.length - 1), h - pad - ((v - min) / (max - min || 1)) * (h - pad * 2)];
  const points = data.map((v, i) => pt(v, i));
  const linea = points.map((p, i) => (i === 0 ? "M" : "L") + p[0] + "," + p[1]).join(" ");
  const area = linea + ` L ${points[points.length - 1][0]},${h - pad} L ${points[0][0]},${h - pad} Z`;
  const gid = "g" + Math.random().toString(36).slice(2);
  return `
    <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:4px;">
      <div><span style="font-size:22px;font-weight:800;">${fmt(actual)}${unidad}</span> <span style="font-size:11px;color:#8B8698;">actual</span></div>
      <div style="font-size:12px;font-weight:700;color:${delta >= 0 ? "#1a9c6e" : "#c94a3a"};">${delta >= 0 ? "▲" : "▼"} ${fmt(Math.abs(delta))}${unidad} desde el inicio</div>
    </div>
    <svg viewBox="0 0 ${w} ${h}" style="width:100%;height:auto;display:block;">
      <defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${color}" stop-opacity="0.35"/>
        <stop offset="100%" stop-color="${color}" stop-opacity="0"/>
      </linearGradient></defs>
      <path d="${area}" fill="url(#${gid})"/>
      <path d="${linea}" fill="none" stroke="${color}" stroke-width="2.5"/>
      ${points.map((p) => `<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="${color}"/>`).join("")}
    </svg>
    <div style="display:flex;justify-content:space-between;font-size:10px;color:#8B8698;">
      <span>Mín: ${fmt(min)}${unidad}</span><span>Máx: ${fmt(max)}${unidad}</span>
    </div>`;
}
// ---------- Biomecánica en el informe ----------
// Arma las series de evolución con las mediciones del apartado Biomecánica (alumno.biomecanica):
// velocidad de barra por ejercicio, altura de salto, frecuencia de ciclo y tiempos de prueba.
function seriesBiomecanica(alumno, enMes = () => true) {
  const evs = (alumno.biomecanica || []).filter((e) => e && typeof e.date === "string" && enMes(e.date)).sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
  const series = {};
  const agregar = (clave, def, fecha, v, detalle) => {
    if (!Number.isFinite(v)) return;
    (series[clave] = series[clave] || { ...def, puntos: [] }).puntos.push({ fecha, v, detalle: detalle || "" });
  };
  evs.forEach((e) => {
    const r = e.summary || {}, d = e.data || {};
    const nombre = (e.title || "").replace(/^(Gym|Técnica) · /, "");
    if (e.kind === "gym" && Number.isFinite(r.mv)) {
      const perdida = d.vl && Number.isFinite(d.vl.v) ? `pérdida de velocidad ${fmtBio(d.vl.v, 1)}%` : "";
      agregar("mv:" + nombre, { titulo: `${nombre} · velocidad media de la mejor repetición`, corto: `${nombre} (velocidad de barra)`, unidad: " m/s", dec: 2, color: "#FF6B35" }, e.date, r.mv, [e.event, perdida].filter(Boolean).join(" · "));
    } else if (e.kind === "gym" && Number.isFinite(r.jump)) {
      agregar("salto", { titulo: "Altura de salto (mejor intento)", corto: "Altura de salto", unidad: " cm", dec: 1, color: "#7DD6C0" }, e.date, r.jump * 100, e.event);
    } else if (e.kind === "tech" && Number.isFinite(r.cycleRate)) {
      agregar("ciclo:" + nombre, { titulo: `${nombre} · frecuencia de ciclo`, corto: `${nombre} (frecuencia de ciclo)`, unidad: " ciclos/min", dec: 1, color: "#5AA0E6" }, e.date, r.cycleRate, e.event);
    } else if ((e.kind === "race" || e.kind === "report") && Number.isFinite(r.finalTime)) {
      const prueba = e.event || nombre;
      agregar("tiempo:" + prueba, { titulo: `${prueba} · tiempo final`, corto: `${prueba} (tiempo)`, unidad: " s", dec: 2, color: "#F2A93B", menorEsMejor: true }, e.date, r.finalTime, "");
    }
  });
  return { evs, series: Object.values(series) };
}
const fmtBio = (v, dec) => v.toLocaleString("es-AR", { minimumFractionDigits: dec, maximumFractionDigits: dec });
// Variación entre la primera y la última medición, con el color según si es una mejora.
function cambioBio(serie) {
  const p = serie.puntos, a = p[0].v, b = p[p.length - 1].v, delta = b - a;
  const mejora = serie.menorEsMejor ? delta < 0 : delta > 0;
  const pct = a ? Math.round((delta / Math.abs(a)) * 100) : null;
  return { a, b, delta, mejora, igual: Math.abs(delta) < Math.pow(10, -serie.dec), pct };
}
// Gráfico de evolución con fechas: mismo estilo que el resto del informe, con el valor de cada punto.
function svgBioChart(serie) {
  const p = serie.puntos;
  if (p.length === 1) {
    return `<div style="display:flex;justify-content:space-between;align-items:baseline;"><div><span style="font-size:22px;font-weight:800;">${fmtBio(p[0].v, serie.dec)}${serie.unidad}</span> <span style="font-size:11px;color:#8B8698;">primera medición · ${mostrarFecha(p[0].fecha)}</span></div></div>`;
  }
  const c = cambioBio(serie);
  const w = 640, h = 150, padX = 34, padTop = 24, padBot = 26;
  const vals = p.map((x) => x.v), max = Math.max(...vals), min = Math.min(...vals);
  const pt = (v, i) => [padX + (i * (w - padX * 2)) / (p.length - 1), padTop + (1 - (v - min) / (max - min || 1)) * (h - padTop - padBot)];
  const pts = p.map((x, i) => pt(x.v, i));
  const linea = pts.map((q, i) => (i === 0 ? "M" : "L") + q[0].toFixed(1) + "," + q[1].toFixed(1)).join(" ");
  const area = linea + ` L ${pts[pts.length - 1][0].toFixed(1)},${h - padBot} L ${pts[0][0].toFixed(1)},${h - padBot} Z`;
  const gid = "b" + Math.random().toString(36).slice(2);
  const colorCambio = c.igual ? "#8B8698" : c.mejora ? "#1a9c6e" : "#c94a3a";
  const flecha = c.igual ? "=" : c.delta > 0 ? "▲" : "▼";
  return `
    <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:4px;">
      <div><span style="font-size:22px;font-weight:800;">${fmtBio(c.b, serie.dec)}${serie.unidad}</span> <span style="font-size:11px;color:#8B8698;">última medición</span></div>
      <div style="font-size:12px;font-weight:700;color:${colorCambio};">${flecha} ${fmtBio(Math.abs(c.delta), serie.dec)}${serie.unidad}${c.pct !== null && !c.igual ? ` (${c.pct > 0 ? "+" : ""}${c.pct}%)` : ""} desde la primera</div>
    </div>
    <svg viewBox="0 0 ${w} ${h}" style="width:100%;height:auto;display:block;">
      <defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${serie.color}" stop-opacity="0.3"/>
        <stop offset="100%" stop-color="${serie.color}" stop-opacity="0"/>
      </linearGradient></defs>
      <line x1="${padX}" y1="${h - padBot}" x2="${w - padX}" y2="${h - padBot}" stroke="#E8E3D8" stroke-width="1"/>
      <path d="${area}" fill="url(#${gid})"/>
      <path d="${linea}" fill="none" stroke="${serie.color}" stroke-width="2.5" stroke-linejoin="round"/>
      ${pts.map((q, i) => `<circle cx="${q[0].toFixed(1)}" cy="${q[1].toFixed(1)}" r="3.5" fill="#fff" stroke="${serie.color}" stroke-width="2"/>
      <text x="${q[0].toFixed(1)}" y="${(q[1] - 9).toFixed(1)}" text-anchor="middle" font-size="10.5" font-weight="700" fill="#121017" font-family="-apple-system,sans-serif">${fmtBio(p[i].v, serie.dec)}</text>
      <text x="${q[0].toFixed(1)}" y="${h - 8}" text-anchor="middle" font-size="9.5" fill="#8B8698" font-family="-apple-system,sans-serif">${mostrarFecha(p[i].fecha)}</text>`).join("")}
    </svg>`;
}
// Frases para el "Análisis final" a partir de las series de biomecánica.
function analisisBiomecanica(series) {
  return series.map((s) => {
    if (s.puntos.length === 1) return `Biomecánica — ${s.corto}: primera medición de ${fmtBio(s.puntos[0].v, s.dec)}${s.unidad}; sirve de base para comparar las próximas.`;
    const c = cambioBio(s);
    if (c.igual) return `Biomecánica — ${s.corto}: se mantuvo estable en ${fmtBio(c.b, s.dec)}${s.unidad} a lo largo de ${s.puntos.length} mediciones.`;
    return `Biomecánica — ${s.corto}: pasó de ${fmtBio(c.a, s.dec)} a ${fmtBio(c.b, s.dec)}${s.unidad}${c.pct !== null ? ` (${c.pct > 0 ? "+" : ""}${c.pct}%)` : ""} en ${s.puntos.length} mediciones, ${c.mejora ? "una mejora" : "un retroceso para revisar"}.`;
  });
}

// Cruza la biomecánica con lo del gimnasio: el RM del mismo ejercicio y las sesiones entrenadas
// entre la primera y la última medición, para leer los avances juntos.
function cruceBiomecanicaGimnasio(alumno, series) {
  const lineas = [];
  const sinTildes = (t) => String(t || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
  const rm = alumno.historialRM || {};
  series.filter((s) => s.corto.includes("velocidad de barra")).forEach((s) => {
    const ej = s.corto.replace(" (velocidad de barra)", "");
    const clave = Object.keys(rm).find((k) => (rm[k] || []).length && (sinTildes(k).includes(sinTildes(ej)) || sinTildes(ej).includes(sinTildes(k))));
    if (!clave) return;
    const v = rm[clave], ini = v[0], fin = v[v.length - 1];
    const cambioVel = s.puntos.length > 1 ? cambioBio(s) : null;
    let t = `${clave}: el RM ${v.length > 1 && fin !== ini ? `pasó de ${ini} a ${fin} kg` : `es de ${fin} kg`}`;
    if (cambioVel && !cambioVel.igual) {
      const subeRM = fin > ini, subeVel = cambioVel.mejora;
      t += subeRM && subeVel ? ` y la velocidad de barra también mejoró: la ganancia de fuerza se ve en la ejecución.` : subeRM && !subeVel ? `, pero la velocidad de barra bajó: puede haber fatiga acumulada, conviene controlar las cargas.` : !subeRM && subeVel ? ` y la velocidad de barra mejoró: se mueve la misma carga más rápido, señal de que el RM puede subir.` : ` y la velocidad de barra bajó: conviene revisar la carga de trabajo y el descanso.`;
    } else t += `.`;
    lineas.push(t);
  });
  const fechas = series.flatMap((s) => s.puntos.map((p) => p.fecha)).sort();
  if (fechas.length > 1 && fechas[0] !== fechas[fechas.length - 1]) {
    const entre = (alumno.historialSesiones || []).filter((f) => f >= fechas[0] && f <= fechas[fechas.length - 1]).length;
    if (entre > 0) lineas.push(`Entre la primera medición (${mostrarFecha(fechas[0])}) y la última (${mostrarFecha(fechas[fechas.length - 1])}) completó ${entre} ${entre === 1 ? "sesión" : "sesiones"} de gimnasio.`);
  }
  return lineas;
}

// Informe solo de biomecánica: mismo formato que el informe individual, con los gráficos de
// evolución, el detalle de cada evaluación y la relación con los avances del gimnasio.
function generarHTMLInformeBiomecanica(alumno) {
  const bio = seriesBiomecanica(alumno);
  const cruce = cruceBiomecanicaGimnasio(alumno, bio.series);
  const analisis = [...analisisBiomecanica(bio.series), ...cruce];
  if (!bio.evs.length) analisis.push("Todavía no hay mediciones de biomecánica guardadas.");
  const rm = alumno.historialRM || {};
  const sinTildes = (t) => String(t || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
  const ejerciciosMedidos = bio.series.filter((s) => s.corto.includes("velocidad de barra")).map((s) => sinTildes(s.corto.replace(" (velocidad de barra)", "")));
  const rmRelacionados = Object.keys(rm).filter((k) => (rm[k] || []).length > 1 && ejerciciosMedidos.some((ej) => sinTildes(k).includes(ej) || ej.includes(sinTildes(k))));
  return `<html><head><meta charset="utf-8"><title>Biomecánica — ${alumno.nombre}</title><style>${ESTILO_INFORME}</style></head><body>
    <button class="btn-imprimir" onclick="window.print()">🖨️ Imprimir / Guardar como PDF</button>
    <div class="hoja">
      <div class="header">
        <div class="marca">🐂 Team Bull · Biomecánica</div>
        <h1>${alumno.nombre}</h1>
        <div class="sub">Informe de biomecánica — ${fechaLegible(todayISO())}</div>
      </div>
      <div class="cuerpo">
        <h2 class="seccion">👤 Perfil</h2>
        <div class="perfil-grid">
          <div class="perfil-item"><b>Edad</b>${alumno.edad || "—"}</div>
          <div class="perfil-item"><b>Peso</b>${alumno.peso ? alumno.peso + " kg" : "—"}</div>
          <div class="perfil-item"><b>Deporte</b>${alumno.deportes || "—"}</div>
          <div class="perfil-item"><b>Objetivo</b>${alumno.objetivo || "—"}</div>
        </div>
        ${seccionBiomecanicaHTML(bio, true)}
        ${cruce.length ? `<h2 class="seccion">🏋️ Relación con el gimnasio</h2>
        <div class="stats">
          <div class="stat"><div class="num">${calcularCumplimiento(alumno)}%</div><div class="label">Cumplimiento</div></div>
          <div class="stat"><div class="num">${alumno.sesionesCompletadas || 0}</div><div class="label">Sesiones completadas</div></div>
        </div>
        ${rmRelacionados.slice(0, 4).map((k) => `<div class="chart-box"><div class="titulo">RM · ${k}</div>${svgLineChart(rm[k], "#121017", "kg")}</div>`).join("")}` : ""}
        <div class="analisis">
          <h3>🔎 Análisis</h3>
          ${analisis.map((p) => `<p>${p}</p>`).join("")}
        </div>
      </div>
      <div class="footer">Generado por Team Bull · Mediciones estimadas por análisis de video</div>
    </div>
  </body></html>`;
}
function descargarInformeBiomecanicaPDF(alumno) {
  const blob = new Blob([generarHTMLInformeBiomecanica(alumno)], { type: "text/html" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `Biomecanica-${slugify(alumno.nombre)}.html`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

