// Sección de biomecánica (gráficos + últimas evaluaciones). completo = versión del informe aparte.
function seccionCruceGymPiletaHTML(alumno) {
  const c = cruceGimnasioPileta(alumno);
  if (!c.rms.length || !(c.mejoras.length + c.empeoro.length)) return "";
  const fila = (izq, der, ok) => `<div style="display:flex;justify-content:space-between;padding:7px 12px;border-bottom:1px solid #EEE;font-size:12px;"><span>${izq}</span><b style="color:${ok ? "#1a9c6e" : "#c94a3a"};">${der}</b></div>`;
  return `<h2 class="seccion">🏋️ Gimnasio y pileta <span style="font-weight:400;text-transform:none;letter-spacing:0;opacity:0.7;">(últimos 3 meses · ${c.sesiones} sesiones de gimnasio)</span></h2>
        <div style="border:1px solid #EEE;border-radius:10px;overflow:hidden;">
          ${c.rms.map((r) => fila(r.ej, `${r.de} → ${r.a} kg`, r.a > r.de)).join("")}
          ${[...c.mejoras, ...c.empeoro].map((x) => fila(x.prueba, `${fmtTiempo(x.de)} → ${fmtTiempo(x.a)} (${x.dif < 0 ? "" : "+"}${x.dif.toFixed(2)} s)`, x.dif < 0)).join("")}
        </div>`;
}

// Sección "Marcas de natación" del informe: mejor marca de cada prueba y cuánto cambió la última.
function seccionMarcasHTML(marcas) {
  if (!Array.isArray(marcas) || !marcas.length) return "";
  const pruebas = {};
  marcas.forEach((m) => { const k = `${m.distancia} ${m.estilo} ${m.pileta || ""}`; (pruebas[k] = pruebas[k] || []).push(m); });
  const filas = Object.values(pruebas).map((ms) => {
    const orden = [...ms].sort((a, b) => (a.fecha || "").localeCompare(b.fecha || ""));
    const mejor = ms.reduce((x, y) => (y.segundos < x.segundos ? y : x));
    const ult = orden[orden.length - 1], ant = orden.length > 1 ? orden[orden.length - 2] : null;
    return { m: ms[0], orden: (ms[0].pileta === "25" ? 100000 : 0) + ESTILOS_NATACION.indexOf(ms[0].estilo) * 10000 + ms[0].distancia, mejor, ult, ant };
  }).sort((a, b) => a.orden - b.orden);
  return `<h2 class="seccion">🏊 Marcas de natación <span style="font-weight:400;text-transform:none;letter-spacing:0;opacity:0.7;">(${filas.length} prueba${filas.length === 1 ? "" : "s"})</span></h2>
        <div style="border:1px solid #EEE;border-radius:10px;overflow:hidden;">
          ${filas.map((f) => {
            const mejoro = f.ant && f.ult.segundos < f.ant.segundos;
            const dif = f.ant ? Math.abs(f.ult.segundos - f.ant.segundos).toFixed(2) : null;
            return `<div style="display:flex;justify-content:space-between;align-items:center;padding:9px 12px;border-bottom:1px solid #EEE;font-size:12px;"><span style="font-weight:600;">${f.m.distancia} ${f.m.estilo}${f.m.pileta ? ` <span style="font-weight:400;color:#8B8698;font-size:10px;">pileta ${f.m.pileta}</span>` : ""}</span><span>Mejor: <b>${fmtTiempo(f.mejor.segundos)}</b>${f.mejor.fecha ? ` <span style="color:#8B8698;font-size:10px;">(${mostrarFecha(f.mejor.fecha)})</span>` : ""}${dif ? ` <span style="color:${mejoro ? "#1a9c6e" : "#c94a3a"};font-size:10px;">${mejoro ? "▼" : "▲"} ${dif}s última</span>` : ""}</span></div>`;
          }).join("")}
        </div>`;
}

function seccionBiomecanicaHTML(bio, completo = false) {
  if (!bio.evs.length) return "";
  return `<h2 class="seccion">🦵 Biomecánica <span style="font-weight:400;text-transform:none;letter-spacing:0;opacity:0.7;">(${bio.evs.length} evaluaci${bio.evs.length === 1 ? "ón" : "ones"} con video)</span></h2>
        <div class="stats">
          <div class="stat"><div class="num">${bio.evs.length}</div><div class="label">Evaluaciones</div></div>
          <div class="stat"><div class="num">${mostrarFecha(bio.evs[bio.evs.length - 1].date)}</div><div class="label">Última medición</div></div>
          ${bio.series.filter((s) => s.puntos.length > 1).length ? `<div class="stat"><div class="num">${bio.series.filter((s) => s.puntos.length > 1 && cambioBio(s).mejora).length}/${bio.series.filter((s) => s.puntos.length > 1).length}</div><div class="label">Medidas que mejoraron</div></div>` : ""}
        </div>
        ${bio.series.map((s) => `<div class="chart-box"><div class="titulo">${s.titulo}</div>${svgBioChart(s)}</div>`).join("")}
        <div style="font-size:9.5px;color:#8B8698;text-transform:uppercase;letter-spacing:1px;font-weight:700;margin:14px 0 8px;">Últimas evaluaciones</div>
        <div style="border:1px solid #EEE;border-radius:10px;overflow:hidden;">
          ${[...bio.evs].reverse().slice(0, completo ? 30 : 8).map((e) => {
            const r = e.summary || {};
            const valor = Number.isFinite(r.mv) ? `${fmtBio(r.mv, 2)} m/s` : Number.isFinite(r.jump) ? `${fmtBio(r.jump * 100, 1)} cm` : Number.isFinite(r.cycleRate) ? `${fmtBio(r.cycleRate, 1)} ciclos/min` : Number.isFinite(r.finalTime) ? `${fmtBio(r.finalTime, 2)} s` : "—";
            return `<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;padding:9px 12px;border-bottom:1px solid #EEE;font-size:12px;"><span><span style="color:#8B8698;font-size:10px;font-weight:700;text-transform:uppercase;margin-right:8px;">${mostrarFecha(e.date)}</span><b>${e.title || "Evaluación"}</b>${e.event ? ` <span style="color:#8B8698;">· ${e.event}</span>` : ""}${completo && e.data && e.data.vl && Number.isFinite(e.data.vl.v) ? ` <span style="color:#8B8698;">· pérdida de velocidad ${fmtBio(e.data.vl.v, 1)}%</span>` : ""}</span><b style="white-space:nowrap;">${valor}</b></div>`;
          }).join("")}
        </div>
        <div style="font-size:10px;color:#8B8698;margin-top:6px;">Mediciones estimadas por análisis de video en el apartado Biomecánica de Team Bull.</div>`;
}

function generarHTMLInforme(alumno, mesFiltro) {
  // mesFiltro opcional, formato "YYYY-MM" — si viene, el informe muestra solo ese mes
  // (check-ins, encuestas, notas); si no viene, muestra todo el historial.
  const enMes = (fechaStr) => !mesFiltro || (typeof fechaStr === "string" && fechaStr.startsWith(mesFiltro));
  const ejerciciosRM = Object.keys(alumno.historialRM || {}).filter((k) => (alumno.historialRM[k] || []).length > 0);
  const checkinsTodos = alumno.wellness?.checkins || [];
  const checkins = checkinsTodos.filter((c) => enMes(c.fecha));
  const promAnimo = checkins.length ? (checkins.reduce((s, c) => s + c.valor, 0) / checkins.length).toFixed(1) : null;
  const encuestas = (alumno.wellness?.encuestas || []).filter((e) => enMes(e.fecha));
  // Promedios de las encuestas post-entreno, para mostrar como gráficos circulares chicos en vez
  // de una lista larga con cada día — así el informe no se hace eterno con muchas semanas cargadas.
  const promedioCampo = (campo) => encuestas.length ? (encuestas.reduce((s, e) => s + (Number(e[campo]) || 0), 0) / encuestas.length).toFixed(1) : null;
  const promFatiga = promedioCampo("fatiga");
  const promSueno = promedioCampo("sueno");
  const promDolor = promedioCampo("dolorMuscular");
  const promMotivacion = promedioCampo("motivacion");
  const comentariosEncuestas = encuestas.filter((e) => e.comentario && e.comentario.trim());
  const notasPorDia = Object.values(alumno.notasEjercicios || {}).filter((n) => n.texto && n.texto.trim() && enMes(n.fecha)).reduce((acc, n) => { (acc[n.fecha] = acc[n.fecha] || []).push(n); return acc; }, {});
  const diasConNotas = Object.entries(notasPorDia).sort((a, b) => (a[0] < b[0] ? 1 : -1));
  const tituloMes = mesFiltro ? new Date(mesFiltro + "-02T00:00:00").toLocaleDateString("es-AR", { month: "long", year: "numeric" }) : null;

  // Check-ins agrupados por semana (Sem.1, Sem.2...) del mes, para el gráfico de barras de constancia
  const checkinsPorSemana = {};
  checkins.forEach((c) => {
    const dia = parseInt(c.fecha.slice(8, 10), 10);
    const semana = Math.ceil(dia / 7);
    checkinsPorSemana[semana] = (checkinsPorSemana[semana] || 0) + 1;
  });
  const semanasLabels = Object.keys(checkinsPorSemana).sort((a, b) => a - b).map((s) => `Sem.${s}`);
  const semanasValores = Object.keys(checkinsPorSemana).sort((a, b) => a - b).map((s) => checkinsPorSemana[s]);

  // Asistencia real del mes (días efectivamente entrenados, según el calendario de sesiones)
  const sesionesDelMes = (alumno.historialSesiones || []).filter((f) => enMes(f)).sort();

  // Resumen del plan actual (mesociclo, objetivo, días de entrenamiento programados)
  const metaPlan = alumno.plan?.meta || {};
  const diasPlan = alumno.plan?.dias || [];

  // Próxima competencia (si está cargada)
  // Próxima competencia (si hay alguna cargada) — la más cercana en el tiempo, entre todas
  const hoyDate = new Date(todayISO() + "T00:00:00");
  const competenciasFuturas = (alumno.competencias || []).filter((c) => c.fecha && new Date(c.fecha + "T00:00:00") >= hoyDate).sort((a, b) => a.fecha < b.fecha ? -1 : 1);
  const competencia = competenciasFuturas[0] || null;

  // Análisis final — un resumen corto en texto, no solo números, cruzando cumplimiento/ánimo/RM
  const analisis = [];
  const cumplimientoCalc = calcularCumplimiento(alumno);
  if (cumplimientoCalc >= 85) analisis.push(`El cumplimiento (${cumplimientoCalc}%) está en un nivel muy bueno.`);
  else if (cumplimientoCalc >= 70) analisis.push(`El cumplimiento (${cumplimientoCalc}%) es aceptable, con margen para mejorar la constancia.`);
  else analisis.push(`El cumplimiento (${cumplimientoCalc}%) está bajo — conviene revisar qué está frenando la asistencia.`);
  if (promAnimo) {
    if (parseFloat(promAnimo) >= 7) analisis.push(`El ánimo se mantuvo alto en general (${promAnimo}/10).`);
    else if (parseFloat(promAnimo) >= 5) analisis.push(`El ánimo estuvo en un nivel medio (${promAnimo}/10), para tener en cuenta.`);
    else analisis.push(`El ánimo promedio fue bajo (${promAnimo}/10) — vale la pena conversarlo con el/la deportista.`);
  }
  if (ejerciciosRM.length) {
    const subieron = ejerciciosRM.filter((ej) => { const v = alumno.historialRM[ej]; return v[v.length - 1] >= v[0]; }).length;
    analisis.push(`De ${ejerciciosRM.length} ejercicio${ejerciciosRM.length === 1 ? "" : "s"} con RM registrado, ${subieron} mostró${subieron === 1 ? "" : "aron"} mejora respecto al valor inicial.`);
  }
  const bio = seriesBiomecanica(alumno, enMes);
  analisis.push(...analisisBiomecanica(bio.series), ...cruceBiomecanicaGimnasio(alumno, bio.series));
  if (sesionesDelMes.length) analisis.push(`Entrenó ${sesionesDelMes.length} día${sesionesDelMes.length === 1 ? "" : "s"} ${tituloMes ? `durante ${tituloMes}` : "en el período mostrado"}.`);

  return `<html><head><meta charset="utf-8"><title>Informe — ${alumno.nombre}</title><style>${ESTILO_INFORME}</style></head><body>
    <button class="btn-imprimir" onclick="window.print()">🖨️ Imprimir / Guardar como PDF</button>
    <div class="hoja">
      <div class="header">
        <div class="marca">🐂 Team Bull · Alto rendimiento</div>
        <h1>${alumno.nombre}</h1>
        <div class="sub">${tituloMes ? `Informe mensual — ${tituloMes}` : `Informe individual — ${fechaLegible(todayISO())}`}</div>
      </div>
      <div class="cuerpo">
        ${competencia && competencia.nombre ? `<div class="destacado">🏆 Próxima competencia: <b>${competencia.nombre}</b>${competencia.fecha ? ` — ${competencia.fecha}` : ""}</div>` : ""}
        <h2 class="seccion">👤 Perfil</h2>
        <div class="perfil-grid">
          <div class="perfil-item"><b>Edad</b>${alumno.edad || "—"}</div>
          <div class="perfil-item"><b>Altura</b>${alumno.altura ? alumno.altura + " cm" : "—"}</div>
          <div class="perfil-item"><b>Peso</b>${alumno.peso ? alumno.peso + " kg" : "—"}</div>
          <div class="perfil-item"><b>Deporte</b>${alumno.deportes || "—"}</div>
          <div class="perfil-item"><b>Objetivo</b>${alumno.objetivo || "—"}</div>
          <div class="perfil-item"><b>Nivel</b>${alumno.nivel || "—"}</div>
          <div class="perfil-item"><b>Equipo</b>${alumno.equipo || "—"}</div>
          <div class="perfil-item"><b>Lesiones</b>${alumno.lesiones || "Ninguna"}</div>
        </div>

        ${diasPlan.length ? `<h2 class="seccion">🗓️ Plan actual</h2>
        <div class="perfil-grid" style="margin-bottom:12px;">
          <div class="perfil-item"><b>Objetivo del mesociclo</b>${metaPlan.objetivo || "—"}</div>
          <div class="perfil-item"><b>Actividad</b>${metaPlan.actividad || "—"}</div>
          <div class="perfil-item"><b>Macrociclo / Mesociclo</b>${metaPlan.macrociclo || "—"} / ${metaPlan.mesociclo || "—"}</div>
          <div class="perfil-item"><b>Descanso entre series</b>${metaPlan.descanso || "—"}</div>
        </div>
        <div class="dias-plan">
          ${diasPlan.map((d) => {
            const totalEj = (d.bloques || []).reduce((n, b) => n + (b.ejercicios || []).length, 0);
            // Tanteo de roles del día — muestra en qué está enfocado el entrenamiento (Fuerza,
            // Estructura, etc.), que dice mucho más que solo la cantidad de ejercicios.
            const conteoRoles = {};
            (d.bloques || []).forEach((b) => (b.ejercicios || []).forEach((ej) => {
              if (!ej.rol) return;
              const rolInfo = ROLES_EJERCICIO.find((r) => r.id === ej.rol);
              const nombreRol = rolInfo ? rolInfo.label : ej.rol;
              conteoRoles[nombreRol] = (conteoRoles[nombreRol] || 0) + 1;
            }));
            const topRoles = Object.entries(conteoRoles).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([n]) => n);
            return `<div class="dia-chip"><b>${d.nombre}</b>${totalEj} ejercicio${totalEj === 1 ? "" : "s"}${topRoles.length ? `<div style="margin-top:5px;font-size:10px;color:#B8763F;font-weight:600;">${topRoles.join(" · ")}</div>` : ""}</div>`;
          }).join("")}
        </div>` : ""}

        <h2 class="seccion">📊 Resumen</h2>
        <div class="donuts">
          ${svgDonutChart(calcularCumplimiento(alumno), 100, "#FF6B35", calcularCumplimiento(alumno) + "%", "Cumplimiento")}
          ${promAnimo ? svgDonutChart(parseFloat(promAnimo), 10, "#33D6A6", promAnimo + "/10", "Ánimo promedio") : ""}
        </div>
        <div class="stats">
          <div class="stat"><div class="num">${alumno.sesionesCompletadas || 0}</div><div class="label">Sesiones</div></div>
          ${alumno.historialPeso && alumno.historialPeso.length ? `<div class="stat"><div class="num">${alumno.historialPeso[alumno.historialPeso.length - 1]}kg</div><div class="label">Peso actual</div></div>` : ""}
        </div>

        ${semanasValores.length > 1 ? `<h2 class="seccion">📅 Constancia — check-ins por semana</h2><div class="chart-box">${svgBarChart(semanasLabels, semanasValores, "#5AA0E6", "")}</div>` : ""}

        ${sesionesDelMes.length ? `<h2 class="seccion">✅ Asistencia${tituloMes ? ` — ${sesionesDelMes.length} sesiones` : ""}</h2><div class="asistencia-dias">${sesionesDelMes.map((f) => `<span class="asistencia-dia">${mostrarFecha(f)}</span>`).join("")}</div>` : ""}

        ${alumno.historialPeso && alumno.historialPeso.length > 1 ? `<h2 class="seccion">⚖️ Evolución de peso corporal</h2><div class="chart-box">${svgLineChart(alumno.historialPeso, "#7DD6C0", "kg")}</div>` : ""}

        ${ejerciciosRM.length ? `<h2 class="seccion">💪 RM por ejercicio <span style="font-weight:400;text-transform:none;letter-spacing:0;opacity:0.7;">(${ejerciciosRM.length} ejercicio${ejerciciosRM.length === 1 ? "" : "s"})</span></h2>
        <div style="border:1px solid #EEE;border-radius:10px;overflow:hidden;">
          ${ejerciciosRM.map((ej) => {
            const vals = alumno.historialRM[ej];
            const actual = vals[vals.length - 1];
            const inicial = vals[0];
            const subio = actual >= inicial;
            const delta = Math.abs(actual - inicial);
            return `<div style="display:flex;justify-content:space-between;align-items:center;padding:9px 12px;border-bottom:1px solid #EEE;font-size:12px;"><span style="font-weight:600;">${ej}</span><span><b>${actual}kg</b> <span style="color:${subio ? "#1a9c6e" : "#c94a3a"};font-size:10px;">${subio ? "▲" : "▼"} ${delta}kg</span></span></div>`;
          }).join("")}
        </div>` : ""}

        ${encuestas.length ? `<h2 class="seccion">📋 Encuestas post-entreno <span style="font-weight:400;text-transform:none;letter-spacing:0;opacity:0.7;">(promedio de ${encuestas.length} registro${encuestas.length === 1 ? "" : "s"})</span></h2>
        <div class="donuts" style="flex-wrap:wrap;gap:10px;">
          ${svgDonutChart(promFatiga, 10, "#E85D5D", promFatiga, "Fatiga", 68)}
          ${svgDonutChart(promSueno, 10, "#5AA0E6", promSueno, "Sueño", 68)}
          ${svgDonutChart(promDolor, 10, "#F2A93B", promDolor, "Dolor muscular", 68)}
          ${svgDonutChart(promMotivacion, 10, "#33D6A6", promMotivacion, "Motivación", 68)}
        </div>
        ${comentariosEncuestas.length ? `<div style="margin-top:10px;">` + comentariosEncuestas.slice(0, 6).map((e) => `<div class="card" style="padding:8px 12px;"><span style="color:#8B8698;font-size:10px;">${mostrarFecha(e.fecha)}:</span> <i style="font-size:12px;">"${e.comentario}"</i></div>`).join("") + `</div>` : ""}` : ""}

        ${diasConNotas.length ? (() => {
          const todasLasNotas = diasConNotas.flatMap(([fecha, notas]) => notas.map((n) => ({ ...n, fecha })));
          const totalNotas = todasLasNotas.length;
          // Contamos cuántas veces aparece cada ejercicio, para mostrar solo un resumen de "en qué
          // se enfocó" en vez de listar cada nota — así el informe no crece con la cantidad de días.
          const conteoPorEjercicio = {};
          todasLasNotas.forEach((n) => { conteoPorEjercicio[n.exNombre] = (conteoPorEjercicio[n.exNombre] || 0) + 1; });
          const masComunes = Object.entries(conteoPorEjercicio).sort((a, b) => b[1] - a[1]).slice(0, 5);
          const ultimasNotas = [...todasLasNotas].sort((a, b) => (a.fecha < b.fecha ? 1 : -1)).slice(0, 5);
          return `<h2 class="seccion">📝 Notas de ejercicios <span style="font-weight:400;text-transform:none;letter-spacing:0;opacity:0.7;">(${totalNotas} en total)</span></h2>
          ${masComunes.length ? `<div style="margin-bottom:14px;">
            <div style="font-size:9.5px;color:#8B8698;text-transform:uppercase;letter-spacing:1px;font-weight:700;margin-bottom:6px;">Ejercicios con más notas</div>
            <div style="display:flex;flex-wrap:wrap;gap:6px;">
              ${masComunes.map(([nombre, n]) => `<span style="background:#F8F6F1;border:1px solid #E8E3D8;border-radius:999px;padding:4px 11px;font-size:11px;font-weight:600;color:#333;">${nombre} <span style="color:#B8763F;font-weight:800;">×${n}</span></span>`).join("")}
            </div>
          </div>` : ""}
          <div style="font-size:9.5px;color:#8B8698;text-transform:uppercase;letter-spacing:1px;font-weight:700;margin-bottom:8px;">Últimas notas</div>
          ${ultimasNotas.map((n) => `<div style="border-left:3px solid #B8763F;background:#F8F6F1;border-radius:0 8px 8px 0;padding:9px 14px;margin-bottom:7px;">
            <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:3px;">
              <span style="font-weight:700;font-size:12px;">${n.exNombre}</span>
              <span style="font-size:9.5px;color:#8B8698;text-transform:uppercase;">${mostrarFecha(n.fecha)}</span>
            </div>
            <div style="font-size:12px;color:#444;font-style:italic;">"${n.texto}"</div>
          </div>`).join("")}
          ${totalNotas > 5 ? `<div style="font-size:10px;color:#8B8698;margin-top:2px;">+ ${totalNotas - 5} notas más este mes.</div>` : ""}`;
        })() : ""}

        ${seccionMarcasHTML(alumno.marcasNatacion)}
        ${seccionCruceGymPiletaHTML(alumno)}

        ${seccionBiomecanicaHTML(bio)}

        ${mesFiltro && !checkins.length && !encuestas.length && !diasConNotas.length ? `<div style="color:#8B8698;font-size:13px;padding:20px 0;text-align:center;">Sin actividad registrada este mes.</div>` : ""}

        ${(() => {
          const fotosMediciones = (alumno.fotosMediciones || []).filter((f) => enMes(f.fecha));
          if (!fotosMediciones.length) return "";
          return `<h2 class="seccion">📸 Fotos de mediciones <span style="font-weight:400;text-transform:none;letter-spacing:0;opacity:0.7;">(${fotosMediciones.length} registro${fotosMediciones.length === 1 ? "" : "s"})</span></h2>
          <div style="display:flex;flex-wrap:wrap;gap:12px;margin-bottom:6px;">
            ${fotosMediciones.map((f) => `<div style="width:150px;background:#F8F6F1;border:1px solid #E8E3D8;border-radius:10px;overflow:hidden;">
              <img src="${f.dataUrl}" style="width:100%;height:150px;object-fit:cover;display:block;" />
              <div style="padding:8px 10px;">
                <div style="font-size:9.5px;color:#8B8698;text-transform:uppercase;letter-spacing:0.5px;font-weight:700;margin-bottom:3px;">${mostrarFecha(f.fecha)}</div>
                ${f.nota && f.nota.trim() ? `<div style="font-size:11px;color:#333;">${f.nota}</div>` : `<div style="font-size:10px;color:#B8B4A8;font-style:italic;">Sin nota</div>`}
              </div>
            </div>`).join("")}
          </div>`;
        })()}

        <div class="analisis">
          <h3>🔎 Análisis final</h3>
          ${analisis.map((p) => `<p>${p}</p>`).join("")}
        </div>
      </div>
      <div class="footer">Generado por Team Bull${tituloMes ? ` — archivo automático de ${tituloMes}` : ""}</div>
    </div>
  </body></html>`;
}
function descargarInformePDF(alumno, mesFiltro) {
  const html = generarHTMLInforme(alumno, mesFiltro);
  const blob = new Blob([html], { type: "text/html" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `Informe-${slugify(alumno.nombre)}${mesFiltro ? `-${mesFiltro}` : ""}.html`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

// Informe completo de UN alumno — combina cumplimiento, peso, RM por ejercicio, bienestar,
// encuestas y notas de ejercicios, todo agrupado prolijo para compartir por WhatsApp, mail, etc.
function generarInformeCompleto(alumno) {
  let t = `🐂 TEAM BULL — Informe individual\n${alumno.nombre}\n${fechaLegible(todayISO())}\n\n`;
  t += `━━━━━━━━━━━━━━\n`;
  t += `📊 GENERAL\n`;
  t += `Cumplimiento: ${calcularCumplimiento(alumno)}%\n`;
  t += `Sesiones completadas: ${alumno.sesionesCompletadas || 0}\n`;
  if (alumno.historialPeso && alumno.historialPeso.length) {
    t += `Peso corporal: ${alumno.historialPeso[alumno.historialPeso.length - 1]}kg actual (arrancó en ${alumno.historialPeso[0]}kg)\n`;
  }
  t += `\n`;

  const ejerciciosRM = Object.keys(alumno.historialRM || {}).filter((k) => (alumno.historialRM[k] || []).length > 0);
  if (ejerciciosRM.length) {
    t += `━━━━━━━━━━━━━━\n💪 RM POR EJERCICIO\n`;
    ejerciciosRM.forEach((ej) => {
      const vals = alumno.historialRM[ej];
      const actual = vals[vals.length - 1];
      const inicial = vals[0];
      const signo = actual >= inicial ? "▲" : "▼";
      t += `${ej}: ${actual}kg actual (${signo} desde ${inicial}kg)\n`;
    });
    t += `\n`;
  }

  const checkins = alumno.wellness?.checkins || [];
  if (checkins.length) {
    const prom = (checkins.reduce((s, c) => s + c.valor, 0) / checkins.length).toFixed(1);
    t += `━━━━━━━━━━━━━━\n🙂 BIENESTAR\n`;
    t += `Ánimo promedio (check-ins): ${prom}/10 · ${checkins.length} registros en total\n\n`;
  }

  const encuestas = alumno.wellness?.encuestas || [];
  if (encuestas.length) {
    t += `━━━━━━━━━━━━━━\n📋 ENCUESTAS POST-ENTRENO\n`;
    encuestas.slice(0, 10).forEach((e) => {
      t += `${mostrarFecha(e.fecha)}: Fatiga ${e.fatiga} · Sueño ${e.sueno} · Dolor ${e.dolorMuscular} · Motivación ${e.motivacion}${e.comentario ? ` — "${e.comentario}"` : ""}\n`;
    });
    t += `\n`;
  }

  const notasPorDia = Object.values(alumno.notasEjercicios || {}).filter((n) => n.texto && n.texto.trim()).reduce((acc, n) => { (acc[n.fecha] = acc[n.fecha] || []).push(n); return acc; }, {});
  const diasConNotas = Object.entries(notasPorDia).sort((a, b) => (a[0] < b[0] ? 1 : -1));
  if (diasConNotas.length) {
    t += `━━━━━━━━━━━━━━\n📝 NOTAS DE EJERCICIOS\n`;
    diasConNotas.forEach(([fecha, notas]) => {
      t += `${mostrarFecha(fecha)}:\n`;
      notas.forEach((n) => { t += `  • ${n.exNombre}: ${n.texto}\n`; });
    });
  }

  return t.trim();
}
function generarInformeSemanal(alumnos) {
  const hoy = new Date(todayISO() + "T00:00:00");
  const haceUnaSemana = new Date(hoy.getTime() - 7 * 24 * 60 * 60 * 1000);
  const enRango = (fechaStr) => {
    // fechas se guardan como ISO (YYYY-MM-DD) o texto libre tipo "13 ago" — solo filtramos las ISO, el resto se muestra igual
    if (/^\d{4}-\d{2}-\d{2}$/.test(fechaStr)) return new Date(fechaStr + "T00:00:00") >= haceUnaSemana;
    return true;
  };
  let t = `🐂 TEAM BULL — Informe semanal\n${fechaLegible(todayISO())}\n\n`;
  alumnos.forEach((a) => {
    t += `━━━━━━━━━━━━━━\n${a.nombre.toUpperCase()} · Cumplimiento: ${calcularCumplimiento(a)}%\n`;
    const checkinsRecientes = (a.wellness.checkins || []).filter((c) => enRango(c.fecha));
    if (checkinsRecientes.length) {
      const prom = (checkinsRecientes.reduce((s, c) => s + c.valor, 0) / checkinsRecientes.length).toFixed(1);
      t += `Ánimo (check-ins): promedio ${prom}/10 (${checkinsRecientes.length} registros)\n`;
    }
    const encuestasRecientes = (a.wellness.encuestas || []).filter((e) => enRango(e.fecha));
    if (encuestasRecientes.length) {
      t += `Encuestas post-entreno:\n`;
      encuestasRecientes.forEach((e) => {
        t += `  • Fatiga ${e.fatiga} · Sueño ${e.sueno} · Dolor ${e.dolorMuscular} · Motivación ${e.motivacion}${e.comentario ? ` — "${e.comentario}"` : ""}\n`;
      });
    }
    const notas = Object.values(a.notasEjercicios || {}).filter((n) => n.texto && n.texto.trim() && enRango(n.fecha));
    if (notas.length) {
      t += `Notas de ejercicios (peso, sensaciones):\n`;
      notas.forEach((n) => { t += `  • ${n.exNombre}: ${n.texto}\n`; });
    }
    const rmCargados = (a.plan?.rm || []).filter((r) => r.valor);
    if (rmCargados.length) {
      t += `Valores de RM cargados:\n`;
      rmCargados.forEach((r) => { t += `  • ${r.ejercicio}: ${r.valor}\n`; });
    }
    if (!checkinsRecientes.length && !encuestasRecientes.length && !notas.length && !rmCargados.length) {
      t += `Sin actividad registrada esta semana.\n`;
    }
    t += `\n`;
  });
  return t;
}

const mkPlanVacio = () => ({ meta: { objetivo: "", actividad: "", macrociclo: "", mesociclo: "", fecha: "", fechaInicio: "", masaAdiposa: "", masaMuscular: "", descanso: "" }, calentamiento: [], dias: [], rm: [] });

const clonarPlan = (p) => ({
  meta: { ...p.meta },
  calentamiento: p.calentamiento.map((w) => ({ ...w, id: uid() })),
  dias: p.dias.map((d) => ({ ...d, id: uid(), bloques: d.bloques.map((b) => ({ ...b, id: uid(), ejercicios: b.ejercicios.map((f) => ({ ...f, id: uid(), semanas: [...f.semanas], rmSemanas: [...(f.rmSemanas || f.semanas.map(() => ""))] })) })) })),
  rm: p.rm.map((r) => ({ ...r, id: uid() })),
});

// Busca el 1RM base cargado (en la tabla de RM del plan) para un ejercicio por nombre — ignora
// mayúsculas, acentos y espacios de más (ej. "Press De Bánca" = "press de banca"), para que no
// haga falta que quede escrito carácter por carácter igual.
function buscarRMBase(rmList, nombreEjercicio) {
  if (!rmList || !nombreEjercicio) return null;
  const norm = (s) => normalizarTexto(s || "").trim().replace(/\s+/g, " ");
  // Primero el nombre idéntico; si no, el mismo ejercicio escrito distinto (ej. "Press de pecho"
  // para "Press banca plano — Con pausa").
  const encontrado = rmList.find((r) => norm(r.ejercicio) === norm(nombreEjercicio) && r.valor) || rmList.find((r) => r.valor && mismoEjercicio(r.ejercicio, nombreEjercicio));
  if (!encontrado) return null;
  const val = parseFloat(String(encontrado.valor).replace(",", "."));
  return Number.isFinite(val) && val > 0 ? val : null;
}

// Extrae TODOS los porcentajes que aparezcan en el texto de prescripción (ej. "80% 85% 100%" o
// "80% · RIR 2 / 85%" -> [80, 85, 100]), para poder calcular una serie progresiva de pesos.
function extraerPorcentajes(texto) {
  if (!texto) return [];
  const coincidencias = String(texto).matchAll(/(\d{1,3}(?:[.,]\d+)?)\s*%/g);
  const valores = [];
  for (const m of coincidencias) {
    const val = parseFloat(m[1].replace(",", "."));
    if (Number.isFinite(val) && val > 0) valores.push(val);
  }
  return valores;
}

// Si la prescripción del ejercicio trae uno o más % (ej. "80% · RIR 2" o "80% 85% 100%" para una
// serie progresiva) Y hay un RM base cargado para ese mismo ejercicio en la tabla de RM del plan,
// calcula el peso (o los pesos) a usar — redondeado a la media unidad más cercana, que es lo
// práctico para cargar discos/mancuernas. Devuelve un array (uno o varios pesos) o null.
function pesosSugeridos(rmList, nombreEjercicio, textoRM) {
  const pcts = extraerPorcentajes(textoRM);
  const base = buscarRMBase(rmList, nombreEjercicio);
  if (!pcts.length || !base) return null;
  return pcts.map((pct) => Math.round(((base * pct) / 100) * 2) / 2);
}

// Sin % pero con RIR (ej. "RIR 2") y las repeticiones de la semana (ej. "3x8" o "4x8/6/4"): peso
// APROXIMADO, contando las reps que harían hasta el fallo (8 + 2 = 10) con la fórmula de Epley
// (10 reps ≈ 75% del RM). Es una guía: el alumno/a elige el peso según cómo se sienta.
function pesosAproxPorRIR(rmList, nombreEjercicio, textoRM, series) {
  if (extraerPorcentajes(textoRM).length) return null;
  const mr = String(textoRM || "").match(/rir\s*(\d+(?:[.,]\d+)?)/i);
  const m = String(series || "").match(/^\s*\d+\s*[x×]\s*(.+)$/i);
  const base = buscarRMBase(rmList, nombreEjercicio);
  if (!mr || !m || !base) return null;
  const rir = parseFloat(mr[1].replace(",", "."));
  const reps = m[1].split("/").map((x) => parseInt(x, 10)).filter((n) => n > 0 && n <= 30);
  if (!reps.length || !(rir >= 0 && rir <= 10)) return null;
  const pesos = reps.map((r) => Math.round((base / (1 + (r + rir) / 30)) * 2) / 2);
  return pesos.filter((p, i) => i === 0 || p !== pesos[i - 1]);
}

// Próximo plan: el coach lo carga antes con la fecha en que empieza. Ese día pasa a ser el plan del
// alumno/a (con esa fecha de inicio) y el anterior queda en "Versiones guardadas". Si el próximo no
// tiene RM cargados, sigue con los del plan anterior; los que sí tiene se suman a su historial de RM.
const primerDiaMesSiguiente = () => { const d = new Date(); return new Date(d.getFullYear(), d.getMonth() + 1, 1, 12).toISOString().slice(0, 10); };
const diaAnteriorISO = (f) => { const d = new Date(f + "T12:00:00"); d.setDate(d.getDate() - 1); return d.toISOString().slice(0, 10); };
// Todo sale de los datos (sin ids nuevos ni "hoy"), así da igual en qué celular se active: el plan
// que ve el alumno/a ese día es exactamente el mismo que después queda guardado.
const planProximoVencido = (a) => !!(a && a.planProximo && a.planProximo.fecha && a.planProximo.fecha <= todayISO());
function activarPlanProximo(a) {
  const pp = a.planProximo;
  const plan = { ...pp.plan, meta: { ...pp.plan.meta, fechaInicio: pp.fecha } };
  if (!plan.rm.length) plan.rm = (a.plan?.rm || []).map((r) => ({ ...r }));
  const idVersion = "proximo-" + (pp.id || pp.fecha);
  const fin = diaAnteriorISO(pp.fecha), inicio = a.plan?.meta?.fechaInicio;
  const mes = new Date(fin + "T12:00:00").toLocaleDateString("es-AR", { month: "long", year: "numeric" }).replace(/ de /, " ");
  const tramo = /^\d{4}-\d{2}-\d{2}$/.test(inicio || "") && inicio <= fin ? `${mostrarFecha(inicio)} al ${mostrarFecha(fin)}` : `hasta el ${mostrarFecha(fin)}`;
  const meso = (a.plan?.meta?.mesociclo || "").trim();
  const anterior = { id: idVersion, nombre: `Plan ${mes.charAt(0).toUpperCase() + mes.slice(1)} (${tramo})${meso ? (/^\d+$/.test(meso) ? " · Mesociclo " : " · ") + meso : ""}`, fecha: pp.fecha, plan: a.plan };
  const historialRM = { ...(a.historialRM || {}) };
  plan.rm.forEach((r) => {
    const v = parseFloat(String(r.valor).replace(",", "."));
    if (!r.ejercicio || !r.ejercicio.trim() || !(v > 0)) return;
    const nombre = ejercicioRelacionado(r.ejercicio, Object.keys(historialRM)) || r.ejercicio.trim();
    const h = historialRM[nombre] || [];
    if (h[h.length - 1] !== v) historialRM[nombre] = [...h, v];
  });
  return { ...a, plan, planProximo: null, historialRM, historialPlanes: [anterior, ...(a.historialPlanes || []).filter((v) => v.id !== idVersion)] };
}

