        <button onClick={() => onSubmit(d)} className="font-body" style={{ width: "100%", background: "#7DD6C0", border: "none", borderRadius: 12, color: "#0B2A2E", fontWeight: 700, fontSize: 14, padding: "13px 0", cursor: "pointer" }}>Enviar encuesta</button>
