// Apartado Biomecánica: la app de análisis de video (SwimBull) vestida con la identidad de
// Team Bull. Vive en public/biomecanica y se muestra acá adentro; todo corre en el celular
// (el video no sale del dispositivo).
// Usa los mismos alumnos de Team Bull: cada medición que se guarda allá llega acá y queda en la
// ficha del alumno (alumno.biomecanica), así se sube a la nube y entra en su informe.
function BiomecanicaScreen({ alumnos, onGuardar, onBorrar }) {
  const frameRef = useRef(null);
  const enviarAlumnos = () => {
    const w = frameRef.current?.contentWindow;
    if (!w) return;
    w.postMessage({ tb: "bio", type: "alumnos", alumnos: alumnos.map((a) => ({ id: a.id, nombre: a.nombre, equipo: a.equipo || "", nivel: a.nivel || "", deportes: a.deportes || "", pruebas: a.pruebasNatacion || "", peso: Number(a.peso) || null, altura: Number(a.altura) || null, bio: a.biomecanica || [] })), nube: { url: SUPABASE_URL, key: SUPABASE_KEY } }, window.location.origin);
  };
  useEffect(() => { enviarAlumnos(); }, [alumnos]);
  useEffect(() => {
    const onMsg = (e) => {
      if (e.origin !== window.location.origin || e.source !== frameRef.current?.contentWindow) return;
      const d = e.data;
      if (!d || d.tb !== "bio") return;
      if (d.type === "hola") enviarAlumnos();
      else if (d.type === "guardar" && d.evaluacion && alumnos.some((a) => a.id === d.alumnoId)) onGuardar(d.alumnoId, d.evaluacion);
      else if (d.type === "borrar" && alumnos.some((a) => a.id === d.alumnoId)) onBorrar(d.alumnoId, d.evaluacionId);
    };
    window.addEventListener("message", onMsg);
    return () => window.removeEventListener("message", onMsg);
  });
  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column", width: "100%", minWidth: 0, overflow: "hidden" }}>
      <TopBar title="Biomecánica" subtitle="Grabá y medí la técnica de cada alumno/a" />
      {/* width 1px + minWidth 100%: en iPhone un iframe se estira al ancho de su contenido si no */}
      <iframe ref={frameRef} src="/biomecanica/index.html" title="Biomecánica" allow="camera; microphone; fullscreen; autoplay; clipboard-write; web-share" allowFullScreen style={{ flex: 1, width: 1, minWidth: "100%", maxWidth: "100%", border: "none", background: "#121017", display: "block" }} />
    </div>
  );
}

function BullLogo({ size = 44 }) {
  return <img src={BULL_LOGO_B64} alt="Team Bull" style={{ width: size, height: "auto", objectFit: "contain", display: "block", margin: "0 auto", filter: "drop-shadow(0 4px 10px rgba(0,0,0,0.5))" }} />;
}

function BuscarGlobal({ alumnos, templates, version, onGoAlumno, onGoPlantillas }) {
  const [q, setQ] = useState("");
  const query = q.trim().toLowerCase();

  const alumnosMatch = useMemo(() => (query ? alumnos.filter((a) => coincideBusqueda(a.nombre, query)) : []), [query, alumnos]);
  const ejerciciosMatch = useMemo(() => (query ? EXERCISES.filter((e) => coincideBusqueda(e.nombre, query)).slice(0, 25) : []), [query, version]);
  const plantillasMatch = useMemo(() => (query ? templates.filter((t) => coincideBusqueda(t.nombre, query)) : []), [query, templates]);

  const sinResultados = query && alumnosMatch.length === 0 && ejerciciosMatch.length === 0 && plantillasMatch.length === 0;

  return (
    <div>
      <TopBar title="Buscar" subtitle="Alumnos/as, ejercicios y plantillas en un solo lugar" />
      <div style={{ padding: "0 20px" }}>
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Buscar cualquier cosa..." className="font-body" autoFocus
          style={{ width: "100%", background: "#1C1A24", border: "1px solid #322E3D", borderRadius: 10, color: "#F4F1EA", padding: "11px 12px", fontSize: 13, marginBottom: 16, boxSizing: "border-box" }} />

        {!query && <div className="font-body" style={{ color: "#8B8698", fontSize: 12, textAlign: "center", padding: 20 }}>Escribí para buscar entre tu plantel, la biblioteca de ejercicios y tus plantillas.</div>}
        {sinResultados && <div className="font-body" style={{ color: "#8B8698", fontSize: 12, textAlign: "center", padding: 20 }}>Sin resultados para "{q}".</div>}

        {alumnosMatch.length > 0 && (
          <div style={{ marginBottom: 18 }}>
            <div className="font-body" style={{ fontSize: 11, color: "#FF6B35", fontWeight: 700, marginBottom: 8 }}>ALUMNOS/AS ({alumnosMatch.length})</div>
            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              {alumnosMatch.map((a) => (
                <button key={a.id} onClick={() => onGoAlumno(a.id)} className="font-body" style={{ display: "flex", alignItems: "center", gap: 10, background: "#1C1A24", border: "1px solid #322E3D", borderRadius: 10, padding: 10, cursor: "pointer", textAlign: "left" }}>
                  <Avatar text={a.foto} foto={a.fotoPerfil} size={28} />
                  <div style={{ flex: 1 }}>
                    <div style={{ color: "#F4F1EA", fontSize: 12, fontWeight: 600 }}>{a.nombre}</div>
                    <div style={{ color: "#8B8698", fontSize: 10 }}>{a.equipo || "Sin equipo"}</div>
                  </div>
                  <span style={{ color: "#8B8698" }}>›</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {ejerciciosMatch.length > 0 && (
          <div style={{ marginBottom: 18 }}>
            <div className="font-body" style={{ fontSize: 11, color: "#7DD6C0", fontWeight: 700, marginBottom: 8 }}>EJERCICIOS ({ejerciciosMatch.length}{ejerciciosMatch.length === 25 ? "+" : ""})</div>
            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              {ejerciciosMatch.map((e) => (
                <button key={e.id} onClick={() => openVideo(e.video)} className="font-body" style={{ display: "flex", alignItems: "center", gap: 10, background: "#1C1A24", border: "1px solid #322E3D", borderRadius: 10, padding: 10, cursor: "pointer", textAlign: "left" }}>
                  <span style={{ fontSize: 16 }}>{e.emoji}</span>
                  <div style={{ flex: 1, color: "#F4F1EA", fontSize: 12, fontWeight: 600 }}>{e.nombre}</div>
                  <span style={{ color: e.color, fontSize: 9, fontWeight: 700 }}>{e.categoria}</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {plantillasMatch.length > 0 && (
          <div style={{ marginBottom: 18 }}>
            <div className="font-body" style={{ fontSize: 11, color: "#8B8698", fontWeight: 700, marginBottom: 8 }}>PLANTILLAS ({plantillasMatch.length})</div>
            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              {plantillasMatch.map((t) => (
                <button key={t.id} onClick={onGoPlantillas} className="font-body" style={{ display: "flex", alignItems: "center", gap: 10, background: "#1C1A24", border: "1px solid #322E3D", borderRadius: 10, padding: 10, cursor: "pointer", textAlign: "left" }}>
                  <div style={{ flex: 1 }}>
                    <div style={{ color: "#F4F1EA", fontSize: 12, fontWeight: 600 }}>{t.nombre}</div>
                    <div style={{ color: "#8B8698", fontSize: 10 }}>{t.categoria} · {t.plan.dias.length} días</div>
                  </div>
                  <span style={{ color: "#8B8698" }}>›</span>
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

const REMEMBER_KEY = "teambull_remember_login";
function cargarLoginRecordado() {
  try {
    const raw = window.localStorage.getItem(REMEMBER_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

function AuthScreen({ onLogin, coaches }) {
  const recordado = useRef(cargarLoginRecordado());
  const [usuario, setUsuario] = useState(recordado.current?.usuario || "");
  const [password, setPassword] = useState(recordado.current?.password || "");
  const [recordar, setRecordar] = useState(!!recordado.current);
  const [error, setError] = useState("");
  const [verPassword, setVerPassword] = useState(false);
  const [recuperando, setRecuperando] = useState(false);
  const [usuarioRecuperar, setUsuarioRecuperar] = useState("");
  const [pinRecuperar, setPinRecuperar] = useState("");
  const [resultadoRecuperar, setResultadoRecuperar] = useState(null);
  const [entrando, setEntrando] = useState(false);
  const intentar = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (entrando) return;
    try {
      const u = usuario.trim(), p = password.trim();
      setEntrando(true);
      const r = await onLogin(u, p);
      setEntrando(false);
      if (r !== true) { setError(typeof r === "string" ? r : "Usuario o contraseña incorrectos."); return; }
      try {
        if (recordar) window.localStorage.setItem(REMEMBER_KEY, JSON.stringify({ usuario: u, password: p }));
        else window.localStorage.removeItem(REMEMBER_KEY);
      } catch {
        // localStorage no disponible: seguimos sin recordar
      }
    } catch (err) {
      setEntrando(false);
      // Si algo se rompe (por ejemplo datos guardados de una versión vieja), avisamos en vez de quedarnos sin hacer nada
      setError(`Hubo un problema al ingresar (${err?.message || "error desconocido"}). Probá restablecer los datos de este dispositivo, abajo.`);
    }
  };
  return (
    <form onSubmit={intentar} style={{ height: "100%", display: "flex", flexDirection: "column", justifyContent: "center", padding: "0 26px" }}>
      <div style={{ marginBottom: 16, textAlign: "center" }}><BullLogo size={170} /></div>
      <div className="font-display" style={{ fontSize: 26, color: "#F4F1EA", fontWeight: 700, marginBottom: 4, letterSpacing: 1, textAlign: "center" }}>TEAM BULL</div>
      <div className="font-body" style={{ fontSize: 12, color: "#8B8698", marginBottom: 24, textAlign: "center" }}>Entrenamiento de alto rendimiento</div>
      <div style={{ marginBottom: 12 }}>
        <div className="font-body" style={{ fontSize: 11, color: "#8B8698", marginBottom: 5 }}>Usuario</div>
        <input value={usuario} onChange={(e) => { setUsuario(e.target.value); setError(""); }} placeholder="tu usuario" name="username" autoComplete="username" className="font-body" style={{ width: "100%", background: "#1C1A24", border: "1px solid #322E3D", borderRadius: 10, color: "#F4F1EA", padding: "11px 12px", fontSize: 13, boxSizing: "border-box" }} />
      </div>
      <div style={{ marginBottom: 10 }}>
        <div className="font-body" style={{ fontSize: 11, color: "#8B8698", marginBottom: 5 }}>Contraseña</div>
        <div style={{ position: "relative" }}>
          <input value={password} onChange={(e) => { setPassword(e.target.value); setError(""); }} type={verPassword ? "text" : "password"} placeholder="••••••" name="current-password" autoComplete="current-password" className="font-body" style={{ width: "100%", background: "#1C1A24", border: "1px solid #322E3D", borderRadius: 10, color: "#F4F1EA", padding: "11px 40px 11px 12px", fontSize: 13, boxSizing: "border-box" }} />
          <button type="button" onClick={() => setVerPassword(!verPassword)} style={{ position: "absolute", right: 10, top: "50%", transform: "translateY(-50%)", background: "none", border: "none", color: "#8B8698", cursor: "pointer", fontSize: 15, padding: 4 }}>{verPassword ? "🙈" : "👁"}</button>
        </div>
      </div>
      <button type="button" onClick={() => setRecuperando(!recuperando)} className="font-body" style={{ background: "none", border: "none", color: "#7DD6C0", fontSize: 11, cursor: "pointer", textAlign: "left", padding: 0, marginBottom: 10 }}>¿Olvidaste tu contraseña?</button>
      {recuperando && (
        <div style={{ background: "#1C1A24", border: "1px solid #322E3D", borderRadius: 10, padding: 12, marginBottom: 12 }}>
          <div className="font-body" style={{ color: "#8B8698", fontSize: 10, marginBottom: 8 }}>Ingresá tu usuario y tu PIN de recuperación (el que configuraste en Ajustes). Si nunca lo configuraste, pedile a otro entrenador que te lo comparta, o escribile a tu coach.</div>
          <input value={usuarioRecuperar} onChange={(e) => setUsuarioRecuperar(e.target.value)} placeholder="Usuario" className="font-body" style={{ width: "100%", background: "#26232F", border: "1px solid #322E3D", borderRadius: 8, color: "#F4F1EA", padding: "8px 10px", fontSize: 12, boxSizing: "border-box", marginBottom: 6 }} />
          <input value={pinRecuperar} onChange={(e) => setPinRecuperar(e.target.value)} placeholder="PIN de recuperación" className="font-body" style={{ width: "100%", background: "#26232F", border: "1px solid #322E3D", borderRadius: 8, color: "#F4F1EA", padding: "8px 10px", fontSize: 12, boxSizing: "border-box", marginBottom: 8 }} />
          <button type="button" onClick={async () => {
            if (MODO_SEGURO) {
              try { const r = await apiDatos({ accion: "recuperar", usuario: usuarioRecuperar.trim(), pin: pinRecuperar.trim() }); setResultadoRecuperar(r.json && typeof r.json.ok === "boolean" ? r.json : { ok: false, texto: "No se pudo consultar. Probá de nuevo." }); }
              catch { setResultadoRecuperar({ ok: false, texto: "Sin conexión: probá de nuevo con internet." }); }
              return;
            }
            const c = (coaches || []).find((co) => co.usuario === usuarioRecuperar.trim());
            if (!c) { setResultadoRecuperar({ ok: false, texto: "No existe ese usuario." }); return; }
            if (!c.recoveryPin) { setResultadoRecuperar({ ok: false, texto: "Ese usuario todavía no configuró un PIN de recuperación.", sinPin: true, telefono: c.telefono || "" }); return; }
            if (c.recoveryPin !== pinRecuperar.trim()) { setResultadoRecuperar({ ok: false, texto: "El PIN no coincide." }); return; }
            setResultadoRecuperar({ ok: true, texto: `Tu contraseña es: ${c.password}` });
          }} className="font-body" style={{ width: "100%", background: "#7DD6C0", border: "none", borderRadius: 8, color: "#0B2A2E", fontWeight: 700, padding: 9, cursor: "pointer" }}>Ver mi contraseña</button>
          {resultadoRecuperar && <div className="font-body" style={{ color: resultadoRecuperar.ok ? "#33D6A6" : "#E85D5D", fontSize: 12, fontWeight: 700, marginTop: 8 }}>{resultadoRecuperar.texto}</div>}
          {resultadoRecuperar?.sinPin && (
            <button
              type="button"
              onClick={() => {
                const texto = encodeURIComponent(`Hola, no puedo recuperar mi contraseña de Team Bull (usuario: ${usuarioRecuperar.trim()}). ¿Me ayudás?`);
                const url = resultadoRecuperar.telefono ? `https://wa.me/${resultadoRecuperar.telefono.replace(/\D/g, "")}?text=${texto}` : `https://wa.me/?text=${texto}`;
                window.open(url, "_blank", "noopener,noreferrer");
              }}
              className="font-body"
              style={{ width: "100%", background: "#25D366", border: "none", borderRadius: 8, color: "#0B2A2E", fontWeight: 700, padding: 9, cursor: "pointer", marginTop: 8 }}
            >💬 Escribirle por WhatsApp</button>
          )}
        </div>
      )}
      <label className="font-body" style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6, cursor: "pointer", userSelect: "none" }}>
        <input type="checkbox" checked={recordar} onChange={(e) => setRecordar(e.target.checked)} style={{ width: 16, height: 16, accentColor: "#FF6B35", cursor: "pointer" }} />
        <span style={{ fontSize: 12, color: "#8B8698" }}>Recordar contraseña en este dispositivo</span>
      </label>
      {error && <div className="font-body" style={{ color: "#E85D5D", fontSize: 11, marginBottom: 10 }}>{error}</div>}
      <button type="submit" className="font-body" style={{ width: "100%", background: "#FF6B35", color: "#121017", border: "none", borderRadius: 12, padding: "13px 0", fontWeight: 700, fontSize: 14, cursor: "pointer", marginTop: 8 }}>{entrando ? "Ingresando..." : "Ingresar"}</button>
      <div className="font-body" style={{ fontSize: 10, color: "#6B6678", marginTop: 14, textAlign: "center" }}>¿Sos alumno/a nuevo/a? Pedile el usuario y la contraseña a tu entrenador.</div>
      <div className="font-body" style={{ fontSize: 9, color: "#4A4658", marginTop: 10, textAlign: "center" }}>Tu navegador también puede ofrecerte guardar esta contraseña.</div>
      <button type="button" onClick={() => { if (window.confirm("¿Restablecer todos los datos guardados en este dispositivo? Esto no se puede deshacer.")) restablecerDatos(); }} className="font-body" style={{ background: "none", border: "none", color: "#4A4658", fontSize: 10, marginTop: 18, cursor: "pointer", textDecoration: "underline" }}>¿No podés entrar? Restablecer datos de este dispositivo</button>
    </form>
  );
}

