  const cambiarPasswordCoach = (coachId, actual, nueva) => {
    const c = coaches.find((co) => co.id === coachId);
    if (!c) return { ok: false, motivo: "No se encontró tu usuario." };
    if (c.password !== actual) return { ok: false, motivo: "La contraseña actual no coincide." };
    if (!nueva || nueva.length < 4) return { ok: false, motivo: "La contraseña nueva necesita al menos 4 caracteres." };
    setCoaches((prev) => prev.map((co) => (co.id === coachId ? { ...co, password: nueva } : co)));
    return { ok: true };
  };
  // El PIN de recuperación permite ver la contraseña propia desde la pantalla de login, sin
  // depender de otro entrenador ni de un mail — cada coach lo configura una vez, de antemano.
  const setRecoveryPin = (coachId, pin) => {
    if (!pin || pin.trim().length < 4) return { ok: false, motivo: "El PIN necesita al menos 4 caracteres." };
    setCoaches((prev) => prev.map((co) => (co.id === coachId ? { ...co, recoveryPin: pin.trim() } : co)));
    return { ok: true };
  };
  // Teléfono de contacto del entrenador — se usa como respaldo cuando alguien quiere recuperar
  // su contraseña pero nunca configuró un PIN: en vez de quedar sin salida, le mostramos un botón
  // directo a WhatsApp para que le escriba a este número.
  const setTelefonoCoach = (coachId, telefono) => {
    setCoaches((prev) => prev.map((co) => (co.id === coachId ? { ...co, telefono: telefono.trim() } : co)));
    return { ok: true };
  };

  // Deshacer: antes de pisar el plan de un/a alumno/a por una copia/asignación, guardamos acá
